return ['domain'=>'vireo-analytics','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','language'=>'ru_RU','project-id-version'=>'Vireo Analytics 0.3.2','pot-creation-date'=>'2026-10-15T14:42:49+00:00','po-revision-date'=>'2026-07-18 12:00+0000','x-generator'=>'WP-CLI 2.12.0','messages'=>['Vireo Analytics'=>'Vireo Analytics','Privacy-first WordPress analytics. Clean dashboard, no cookies, no consent banners, no third-party tracking.'=>'Аналитика WordPress с приоритетом конфиденциальности. Понятная панель, без cookie, без баннеров согласия, без стороннего отслеживания.','RebelCode'=>'RebelCode','https://rebelcode.com'=>'https://rebelcode.com','Vireo Analytics backup'=>'Резервная копия Vireo Analytics','That file is larger than this server accepts (%s). Ask your host to raise the upload limit, or restore in smaller pieces.'=>'Этот файл больше, чем принимает сервер (%s). Попросите хостинг-провайдера увеличить лимит загрузки или восстановите данные по частям.','The upload did not complete. Try again.'=>'Загрузка не завершилась. Повторите попытку.','The uploads directory is not writable, so the file cannot be kept while it is read.'=>'Папка загрузок недоступна для записи, поэтому файл нельзя сохранить на время чтения.','The file could not be saved for reading.'=>'Не удалось сохранить файл для чтения.','The file could not be opened.'=>'Не удалось открыть файл.','The file is damaged: a line could not be read.'=>'Файл повреждён: не удалось прочитать одну из строк.','The file ends early. It may not have finished downloading; export it again.'=>'Файл обрывается раньше времени. Возможно, он скачался не полностью; экспортируйте его заново.','That is not a Vireo Analytics backup. Use the file from Settings, Import & export, Download backup.'=>'Это не резервная копия Vireo Analytics. Используйте файл из раздела «Настройки» → «Импорт и экспорт» → «Скачать резервную копию».','This backup was made by a newer version of Vireo Analytics. Update the plugin here, then try again.'=>'Эта резервная копия создана в более новой версии Vireo Analytics. Обновите плагин на этом сайте и повторите попытку.','Upload a backup file first.'=>'Сначала загрузите файл резервной копии.','The uploaded file is no longer available. Upload it again.'=>'Загруженный файл больше недоступен. Загрузите его ещё раз.','Restored. %d part of the file was for a table this version does not have and was skipped.'=>'Восстановлено. %d часть файла относилась к таблице, которой нет в этой версии, и была пропущена.' . "\0" . 'Восстановлено. %d части файла относились к таблицам, которых нет в этой версии, и были пропущены.' . "\0" . 'Восстановлено. %d частей файла относились к таблицам, которых нет в этой версии, и были пропущены.','Restored.'=>'Восстановлено.','Restoring %s'=>'Восстановление: %s','daily totals'=>'итоги по дням','bounce rates'=>'показатели отказов','hourly totals'=>'итоги по часам','pages'=>'страницы','time on page'=>'время на странице','referrers'=>'источники переходов','referrers per page'=>'реферы по страницам','countries'=>'страны','devices'=>'устройства','missing pages'=>'отсутствующие страницы','events'=>'события','bot traffic'=>'трафик ботов','Core Web Vitals'=>'Core Web Vitals','chart notes'=>'заметки на графиках','Search Console queries'=>'запросы Search Console','Search Console pages'=>'страницы Search Console','Burst Statistics'=>'Burst Statistics','No Burst Statistics data found.'=>'Данные Burst Statistics не найдены.','Burst Statistics import complete.'=>'Импорт Burst Statistics завершён.','Imported %1$d of %2$d day from Burst Statistics.'=>'Импортирован %1$d из %2$d дня из Burst Statistics.' . "\0" . 'Импортировано %1$d из %2$d дней из Burst Statistics.' . "\0" . 'Импортировано %1$d из %2$d дней из Burst Statistics.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices and missing pages.'=>'Переносит ежедневные просмотры и посетителей, ваши страницы, источники переходов, записи, на которые каждый источник привёл читателей, страны, браузеры, операционные системы, устройства и несуществующие страницы.','Google Analytics 4'=>'Google Analytics 4','Add the service account key and the GA4 property ID first.'=>'Сначала добавьте ключ сервисного аккаунта и ID ресурса GA4.','The date range is not valid.'=>'Указан недопустимый диапазон дат.','Imported %1$s to %2$s'=>'Импортировано с %1$s по %2$s','Google refused the request. Check the service account has Viewer access on this GA4 property.'=>'Google отклонил запрос. Проверьте, что у сервисного аккаунта есть доступ на просмотр (Viewer) к этому ресурсу GA4.','Google Analytics returned an unexpected response (HTTP %d).'=>'Google Analytics вернул неожиданный ответ (HTTP %d).','Google Analytics returned a response we could not read.'=>'Google Analytics вернул ответ, который не удалось прочитать.','Import complete'=>'Импорт завершён','Import stopped'=>'Импорт остановлен','Independent Analytics'=>'Independent Analytics','No Independent Analytics data found.'=>'Данные Independent Analytics не найдены.','Independent Analytics import complete.'=>'Импорт Independent Analytics завершён.','Imported %1$d of %2$d day from Independent Analytics.'=>'Импортирован %1$d из %2$d дня из Independent Analytics.' . "\0" . 'Импортировано %1$d из %2$d дней из Independent Analytics.' . "\0" . 'Импортировано %1$d из %2$d дней из Independent Analytics.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices, missing pages, and tracked link clicks and form submissions as events.'=>'Переносит ежедневные просмотры и посетителей, ваши страницы, источники переходов, записи, на которые каждый источник привёл читателей, страны, браузеры, операционные системы, устройства, несуществующие страницы, а также клики по отслеживаемым ссылкам и отправки форм в виде событий.','Jetpack Stats'=>'Jetpack Stats','Importing %1$s — %2$s'=>'Импорт %1$s — %2$s','Missing import parameters. Please submit the form again.'=>'Отсутствуют параметры импорта. Отправьте форму ещё раз.','Invalid date range — please use YYYY-MM-DD.'=>'Неверный диапазон дат — используйте формат ГГГГ-ММ-ДД.','End date must be on or after start date.'=>'Дата окончания должна быть не раньше даты начала.','Complete'=>'Готово','Could not reach Jetpack Stats API: %s'=>'Не удалось подключиться к API Jetpack Stats: %s','Unexpected (non-JSON) response from Jetpack Stats API.'=>'Неожиданный ответ (не JSON) от API Jetpack Stats.','Invalid or unauthorized API key. Copy your WordPress.com API key from Jetpack → Settings → Security → Akismet.'=>'Неверный или неавторизованный ключ API. Скопируйте ключ API WordPress.com из Jetpack → Настройки → Безопасность → Akismet.','Jetpack Stats API is rate-limiting — please wait a minute and try again.'=>'API Jetpack Stats ограничивает частоту запросов — подождите минуту и повторите попытку.','Jetpack Stats API is unavailable right now. Please retry in a few minutes.'=>'API Jetpack Stats сейчас недоступен. Повторите попытку через несколько минут.','Jetpack Stats API returned an error (HTTP %d). Check your API key and blog URI.'=>'API Jetpack Stats вернул ошибку (HTTP %d). Проверьте ключ API и адрес блога.','Koko Analytics'=>'Koko Analytics','No Koko Analytics data found.'=>'Данные Koko Analytics не найдены.','Plausible Analytics'=>'Plausible Analytics','No Plausible reports were found in that upload. Upload the zip file Plausible emailed you, or the CSV files inside it.'=>'В загруженном файле не найдено отчётов Plausible. Загрузите ZIP-архив, который Plausible отправил вам по почте, или CSV-файлы из него.','The export has no traffic in the dates you chose.'=>'В экспорте нет данных о трафике за выбранные даты.','Upload a Plausible export first.'=>'Сначала загрузите экспорт Plausible.','The uploaded export is no longer available. Upload it again; dates already imported are listed on this screen.'=>'Загруженный экспорт больше недоступен. Загрузите его снова: уже импортированные даты перечислены на этом экране.','The file did not upload. It may be larger than this server accepts.'=>'Файл не загрузился. Возможно, он превышает размер, допустимый на этом сервере.','That file is too large. Export a shorter date range from Plausible and import it in parts.'=>'Файл слишком большой. Экспортируйте из Plausible более короткий период и импортируйте данные частями.','Upload the .zip file Plausible gave you, or the .csv files inside it.'=>'Загрузите ZIP-файл, который вам дал Plausible, или CSV-файлы из него.','The uploaded file could not be read.'=>'Не удалось прочитать загруженный файл.','This server cannot open zip files. Unzip the export on your computer and upload the CSV files instead.'=>'Этот сервер не умеет открывать ZIP-архивы. Распакуйте экспорт на своём компьютере и загрузите CSV-файлы.','That zip file could not be opened.'=>'Не удалось открыть этот ZIP-архив.','That zip holds more files than a Plausible export does.'=>'В этом ZIP-архиве больше файлов, чем бывает в экспорте Plausible.','A file inside the zip could not be read.'=>'Не удалось прочитать один из файлов внутри ZIP-архива.','The %1$s file is missing its %2$s column.'=>'В файле %1$s отсутствует столбец %2$s.','That export is too large to import in one go. Choose a shorter date range and import it in parts.'=>'Этот экспорт слишком велик, чтобы импортировать его за один раз. Выберите более короткий период и импортируйте данные частями.','SlimStat Analytics'=>'SlimStat Analytics','No SlimStat data found.'=>'Данные SlimStat не найдены.','SlimStat import complete.'=>'Импорт SlimStat завершён.','Imported %1$d of %2$d day from SlimStat.'=>'Импортирован %1$d из %2$d дня из SlimStat.' . "\0" . 'Импортировано %1$d из %2$d дней из SlimStat.' . "\0" . 'Импортировано %1$d из %2$d дней из SlimStat.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices, missing pages, downloads and outbound clicks, and the crawlers SlimStat recorded, as filtered bots rather than visits.'=>'Переносит ежедневные просмотры и посетителей, ваши страницы, источники переходов, записи, на которые каждый источник привёл читателей, страны, браузеры, операционные системы, устройства, несуществующие страницы, загрузки и клики по внешним ссылкам, а также краулеры, зафиксированные SlimStat, как отфильтрованных ботов, а не визиты.','Statify'=>'Statify','No Statify data found.'=>'Данные Statify не найдены.','Statify import complete.'=>'Импорт Statify завершён.','Imported %1$d of %2$d day from Statify.'=>'Импортирован %1$d из %2$d дня из Statify.' . "\0" . 'Импортировано %1$d из %2$d дней из Statify.' . "\0" . 'Импортировано %1$d из %2$d дней из Statify.','Brings across daily pageviews, your pages, referrers and which posts each referrer sent readers to. Statify does not identify visitors, so imported days have no visitor counts.'=>'Переносит ежедневные просмотры, ваши страницы, источники переходов и записи, на которые каждый источник привёл читателей. Statify не идентифицирует посетителей, поэтому у импортированных дней нет данных о количестве посетителей.','WP Statistics'=>'WP Statistics','No WP Statistics data found.'=>'Данные WP Statistics не найдены.','WP Statistics import complete.'=>'Импорт WP Statistics завершён.','Imported %1$d of %2$d day from WP Statistics.'=>'Импортирован %1$d из %2$d дня из WP Statistics.' . "\0" . 'Импортировано %1$d из %2$d дней из WP Statistics.' . "\0" . 'Импортировано %1$d из %2$d дней из WP Statistics.','Brings across daily pageviews and visitors, your pages, referrers, which posts each referrer sent readers to, countries, browsers, operating systems, devices, missing pages, link clicks, downloads and custom events, and, if WP Statistics recorded exclusions, the bots it filtered out.'=>'Переносит ежедневные просмотры и посетителей, ваши страницы, источники переходов, записи, на которые каждый источник привёл читателей, страны, браузеры, операционные системы, устройства, несуществующие страницы, клики по ссылкам, загрузки и произвольные события, а также ботов, отфильтрованных WP Statistics, если плагин записывал исключения.','Read-only site analytics: traffic, pages, referrers, geography, devices, and events.'=>'Аналитика сайта только для чтения: трафик, страницы, источники переходов, география, устройства и события.','Get traffic totals'=>'Получить сводку по трафику','Total pageviews, unique visitors, average daily pageviews, average time on page and bounce rate for a date range (defaults to the last 30 days). Time on page is active time (the tab in front of the reader, at most 30 minutes a view), averaged over the views that reported one. Bounce rate is the percentage of visitors who viewed exactly one page in a day. Both are null until there is data for the range.'=>'Общее число просмотров страниц, уникальные посетители, среднее число просмотров страниц в день, среднее время на странице и показатель отказов за выбранный период (по умолчанию за последние 30 дней). Время на странице — это активное время (вкладка открыта перед читателем, не более 30 минут на просмотр), усреднённое по просмотрам, для которых оно было передано. Показатель отказов — это доля посетителей, просмотревших ровно одну страницу за день. Оба значения равны null, пока за период нет данных.','Get daily traffic series'=>'Получить ежедневный ряд трафика','Per-day pageviews and visitors over a date range, for charting trends.'=>'Просмотры страниц и посетители по дням за период — для построения графиков трендов.','Get top pages'=>'Получить топ страниц','Most-viewed pages for a date range, ranked by pageviews, with each page\'s average active time on page in seconds (null when no view of it reported a time).'=>'Самые просматриваемые страницы за выбранный период, отсортированные по числу просмотров, со средним активным временем на каждой странице в секундах (null, если ни один просмотр не передал время).','Get top referrers'=>'Получить топ источников переходов','Top referring sites sending traffic for a date range.'=>'Сайты, приведшие больше всего трафика за период.','Get traffic by country'=>'Получить трафик по странам','Visitor counts broken down by country for a date range.'=>'Число посетителей с разбивкой по странам за период.','Get device breakdown'=>'Получить разбивку по устройствам','Visitor breakdown by browser, operating system, and device type for a date range.'=>'Разбивка посетителей по браузерам, операционным системам и типам устройств за период.','Get custom events'=>'Получить пользовательские события','Top custom events for a date range. Pass a `name` to break a single event down by value.'=>'Топ пользовательских событий за период. Передайте `name`, чтобы разбить отдельное событие по значениям.','Optional event name to break down by value.'=>'Необязательное имя события для разбивки по значениям.','Get stats for a post'=>'Получить статистику по записи','Lifetime and date-range pageviews/visitors, a daily series, and the top referrers for a single post or page. Use get-top-pages first if you only have a title or path.'=>'Просмотры и посетители за всё время и за выбранный период, ежедневная динамика и основные реферреры для одной записи или страницы. Если известны только заголовок или путь, сначала вызовите get-top-pages.','The post or page ID to report on.'=>'ID записи или страницы для отчёта.','Get hourly traffic series'=>'Получить почасовую динамику трафика','Pageviews and visitors per hour, for "what time of day do people visit" and for looking at today or yesterday in detail. Covers at most two days; longer ranges are cut to the last two days. Defaults to today.'=>'Просмотры и посетители по часам: для вопросов вроде «в какое время суток заходят посетители» и для подробного взгляда на сегодня или вчера. Охватывает не более двух дней, более длинные периоды обрезаются до последних двух дней. По умолчанию берётся сегодня.','Get what changed'=>'Получить изменения','What changed against the previous period of the same length: a one-sentence summary, the pages and traffic sources that gained or lost the most, shifts in the traffic mix, and health warnings such as tracking having stopped or a 404 spike. Call this first when asked "how is the site doing" or "why is traffic up/down".'=>'Что изменилось по сравнению с предыдущим периодом такой же длины: краткий вывод в одном предложении, страницы и источники трафика с наибольшим приростом или потерями, сдвиги в структуре трафика и предупреждения о состоянии, например остановка отслеживания или всплеск ошибок 404. Вызывайте это в первую очередь, когда спрашивают «как дела у сайта» или «почему трафик вырос/упал».','Get weekly highlights'=>'Получить итоги недели','Short, ready-to-quote highlights for a finished week: milestones crossed, the biggest gaining page, a new referrer, the best day. Defaults to the last seven full days. Returns an empty list when nothing stood out.'=>'Короткие итоги завершившейся недели, готовые к цитированию: пройденные рубежи, страница с наибольшим приростом, новый реферер, лучший день. По умолчанию берутся последние семь полных дней. Если ничего примечательного не было, возвращает пустой список.','Get traffic by channel'=>'Получить трафик по каналам','Pageviews and visitors grouped by how people arrived: direct, search engines, AI assistants, social networks, and other referring sites, with each channel\'s share. Use get-top-referrers for the individual sites inside a channel.'=>'Просмотры и посетители, сгруппированные по тому, как люди пришли: прямые заходы, поисковые системы, ИИ-ассистенты, соцсети и другие сайты-источники, с долей каждого канала. Чтобы увидеть отдельные сайты внутри канала, используйте get-top-referrers.','Get stats for one referrer'=>'Получить статистику по одному реферреру','Everything about traffic from one referring site: pageviews and visitors in the range, a daily series, and which of your pages it sent people to. Pass the host as shown by get-top-referrers, for example "news.ycombinator.com".'=>'Всё о трафике с одного сайта-источника: просмотры и посетители за период, ежедневная динамика и страницы вашего сайта, на которые он привёл людей. Передайте хост в том виде, как его показывает get-top-referrers, например «news.ycombinator.com».','The referring site, as a hostname or URL.'=>'Сайт-источник в виде имени хоста или URL.','Get AI assistant traffic'=>'Получить трафик от ИИ-ассистентов','What AI assistants take and what they send back: requests made by AI crawlers (GPTBot, ClaudeBot, PerplexityBot and others) against readers (visitors) that ChatGPT, Claude, Perplexity, Gemini and the rest referred to the site, per assistant, with the ratio of crawler requests per reader sent. Everything covers the days crawlers were counted; when that starts later than the requested range, `since` holds that date.'=>'Что AI-ассистенты забирают с сайта и что присылают взамен: запросы AI-краулеров (GPTBot, ClaudeBot, PerplexityBot и других) в сопоставлении с читателями (посетителями), которых ChatGPT, Claude, Perplexity, Gemini и остальные направили на сайт, по каждому ассистенту, с соотношением запросов краулеров на одного присланного читателя. Все данные охватывают дни, за которые краулеры учитывались; если этот период начинается позже запрошенного диапазона, в поле `since` указана эта дата.','Get Google Search Console data'=>'Получить данные Google Search Console','Google Search performance synced from Search Console: site-wide clicks, impressions, CTR and average position plus the top search queries, or, when post_id or path is given, the queries that brought people to that one page. Returns connected=false with no data when Search Console is not connected under Settings. Google\'s data lags two to three days behind.'=>'Эффективность в поиске Google, синхронизированная из Search Console: клики, показы, CTR и средняя позиция по всему сайту, а также топ поисковых запросов или, если указан post_id или path, запросы, по которым люди приходили на эту конкретную страницу. Если Search Console не подключена в разделе «Настройки», возвращает connected=false без данных. Данные Google отстают на два-три дня.','Optional post or page ID to get the queries for that page only.'=>'Необязательный ID записи или страницы, чтобы получить запросы только для этой страницы.','Optional page path (for example /pricing) instead of post_id.'=>'Необязательный путь страницы (например, /pricing) вместо post_id.','Get stats for one event'=>'Получить статистику по одному событию','One custom event in depth: total and unique counts, a daily series, how many distinct values it carried, and the top values. Use get-events to find event names first.'=>'Одно пользовательское событие подробно: общее и уникальное количество, ежедневная динамика, сколько различных значений оно содержало и самые частые значения. Названия событий сначала найдите через get-events.','The event name, as listed by get-events.'=>'Название события в том виде, как его показывает get-events.','Get missing pages (404s)'=>'Получить несуществующие страницы (404)','Paths that returned 404, ranked by hits. Split into broken links (reached from one of your own pages, with the page that links there, so they can be fixed) and probes (scanners and outside links). Use this for "do I have broken links" and for a 404 spike flagged by get-changes.'=>'Пути, которые вернули 404, по убыванию числа обращений. Разделены на битые ссылки (переход с одной из ваших страниц, с указанием страницы со ссылкой, чтобы их можно было исправить) и пробы (сканеры и внешние ссылки). Используйте это для вопросов «есть ли у меня битые ссылки» и для всплеска 404, отмеченного в get-changes.','Get bot and crawler traffic'=>'Получить трафик ботов и краулеров','Requests the bot filter rejected, per category (search engines, AI crawlers, SEO tools, monitors, scrapers and so on), with the share of all requests they made up. None of these are in the pageview totals; use this when numbers look lower than another tool\'s, or when asked how much AI crawlers read the site.'=>'Запросы, которые отклонил фильтр ботов, по категориям (поисковые системы, ИИ-краулеры, SEO-инструменты, мониторинг, парсеры и так далее) с долей от всех запросов. Ни один из них не входит в итоги просмотров; используйте это, когда цифры ниже, чем в другом инструменте, или когда спрашивают, как много читают сайт ИИ-краулеры.','Get Core Web Vitals'=>'Получить Core Web Vitals','Core Web Vitals (LCP, INP, CLS) measured on real visitors, reported at the 75th percentile the way Google grades them, each with a good/needs-improvement/poor rating and the sample count. Empty when no measurements were recorded in the range.'=>'Core Web Vitals (LCP, INP, CLS), измеренные на реальных посетителях и приведённые по 75-му процентилю, как их оценивает Google, каждый с оценкой «хорошо» / «требует улучшения» / «плохо» и количеством замеров. Пусто, если за выбранный период замеры не записывались.','Get chart notes'=>'Получить заметки к графику','Notes the site owner pinned to dates on the traffic chart, such as "newsletter sent" or "redesign launched". Check these when explaining a spike or a dip, since they often hold the reason.'=>'Заметки, которые владелец сайта привязал к датам на графике трафика, например «отправлена рассылка» или «запущен редизайн». Загляните в них, когда объясняете всплеск или спад: часто причина указана именно там.','Get year in review'=>'Получить итоги года','The year in review for one calendar year: totals against the year before, the busiest month and day, the top pages, posts published that year, top referrers, countries, and AI crawler activity. Includes imported history from a previous analytics tool. Defaults to the current year.'=>'Итоги одного календарного года: общие показатели по сравнению с предыдущим годом, самые активные месяц и день, популярные страницы, записи, опубликованные в этом году, основные реферальные источники, страны и активность ИИ-краулеров. Включает импортированную историю из прежнего инструмента аналитики. По умолчанию берётся текущий год.','The calendar year to report on. Defaults to the current year.'=>'Календарный год для отчёта. По умолчанию берётся текущий год.','Get goal completions (Pro)'=>'Получить достижения целей (Pro)','Conversion goals with completion counts and total value for a date range. Requires Vireo Analytics Pro.'=>'Цели конверсии с числом достижений и суммарной ценностью за период. Требуется Vireo Analytics Pro.','Post not found.'=>'Запись не найдена.','Goals feature unavailable.'=>'Функция целей недоступна.','Direct'=>'Прямые','Search'=>'Поиск','AI assistants'=>'ИИ-ассистенты','Social'=>'Соцсети','Referral'=>'Реферальные','host must be a hostname or URL.'=>'host должен быть именем хоста или URL.','Google Search Console is not connected. Connect it under Vireo Analytics, Settings, Search Console & API.'=>'Google Search Console не подключена. Подключите её в разделе Vireo Analytics → Настройки → Search Console и API.','name is required.'=>'Необходимо указать name.','year must be a calendar year with data, no later than the current year.'=>'year должен быть календарным годом, за который есть данные, не позже текущего.','Unknown ability.'=>'Неизвестная возможность.','Start date (YYYY-MM-DD). Defaults to 30 days ago.'=>'Дата начала (ГГГГ-ММ-ДД). По умолчанию 30 дней назад.','End date (YYYY-MM-DD). Defaults to today.'=>'Дата окончания (ГГГГ-ММ-ДД). По умолчанию сегодня.','Maximum number of rows to return (1-100).'=>'Максимальное число возвращаемых строк (1–100).','pageviews today'=>'просмотров сегодня','Pageviews today (Vireo Analytics)'=>'Просмотров сегодня (Vireo Analytics)','Vireo Analytics is not recording.'=>'Vireo Analytics не записывает данные.','%1$s. %2$d attempts have failed over the last %3$s. Visits are still being written to disk and will be counted once this clears.'=>'%1$s. За последние %3$s не удалось выполнить %2$d попыток. Посещения по-прежнему записываются на диск и будут учтены, как только проблема будет устранена.','Aggregation is failing'=>'Сбор данных не выполняется','Pick a real date.'=>'Укажите настоящую дату.','Add a short note to go with the date.'=>'Добавьте короткую заметку к этой дате.','Could not save that note.'=>'Не удалось сохранить заметку.','That site is no longer connected.'=>'Этот сайт больше не подключён.','You are not allowed to add notes.'=>'У вас нет прав на добавление заметок.','You are not allowed to remove notes.'=>'У вас нет прав на удаление заметок.','That note is already gone.'=>'Эта заметка уже удалена.','Forbidden.'=>'Доступ запрещён.','Failed to open output stream.'=>'Не удалось открыть поток вывода.','AI crawlers'=>'ИИ-краулеры','Search engines'=>'Поисковые системы','SEO tools'=>'SEO-инструменты','Uptime monitors'=>'Мониторинг доступности','Link previews'=>'Предпросмотр ссылок','Automated browsers'=>'Автоматизированные браузеры','Scripts and clients'=>'Скрипты и клиенты','Archivers and validators'=>'Архиваторы и валидаторы','Prefetch and prerender'=>'Предзагрузка и пререндеринг','Repeated views past the daily cap'=>'Повторные просмотры сверх дневного лимита','Referrer spam'=>'Реферальный спам','Other bots'=>'Прочие боты','%s comment'=>'%s комментарий' . "\0" . '%s комментария' . "\0" . '%s комментариев','%s per 1,000 views'=>'%s на 1 000 просмотров','Traffic chart'=>'График трафика','What changed'=>'Что изменилось','Top pages'=>'Топ страниц','Top referrers'=>'Источники переходов','Top countries'=>'Топ стран','Technology'=>'Технологии','Pageviews today'=>'Просмотров сегодня','Compared with yesterday up to the same time of day.'=>'Сравнение со вчерашним днём на тот же час.','Visitors today'=>'Посетителей сегодня','Right now'=>'Сейчас','Last 14 days'=>'Последние 14 дней','Pageviews'=>'Просмотры','Visitors'=>'Посетители','Pageviews, compared with the period before'=>'Просмотры в сравнении с предыдущим периодом','7 days'=>'7 дней','30 days'=>'30 дней','90 days'=>'90 дней','Top pages · last 7 days'=>'Топ страниц · за 7 дней','Top referrers · last 7 days'=>'Источники переходов · за 7 дней','View full dashboard →'=>'Открыть полную панель →','No data yet.'=>'Пока нет данных.','Home'=>'Главная','No traffic data yet.'=>'Пока нет данных о трафике.','%1$s: %2$s pageviews, %3$s visitors'=>'%1$s: просмотров %2$s, посетителей %3$s','Pageviews and visitors, last 14 days'=>'Просмотры и посетители за последние 14 дней','Day'=>'День','Overview'=>'Обзор','Search & AI'=>'Поиск и ИИ','Page speed'=>'Скорость страниц','Content'=>'Контент','Campaigns'=>'Кампании','Issues'=>'Проблемы','Starting…'=>'Запуск…','Import complete.'=>'Импорт завершён.','Something went wrong:'=>'Что-то пошло не так:','Import cancelled.'=>'Импорт отменён.','today'=>'сегодня','yesterday'=>'вчера','last 7 days'=>'последние 7 дней','last 14 days'=>'последние 14 дней','last 30 days'=>'последние 30 дней','last 90 days'=>'последние 90 дней','this month'=>'этот месяц','last month'=>'прошлый месяц','year to date'=>'с начала года','Traffic overview · %s'=>'Обзор трафика · %s','Traffic overview · %1$s – %2$s'=>'Обзор трафика · %1$s – %2$s','(no path)'=>'(нет пути)','Unknown'=>'Неизвестно','Desktop'=>'Компьютер','Mobile'=>'Мобильный','Tablet'=>'Планшет','%s visitor vs the prior period'=>'%s посетитель по сравнению с предыдущим периодом' . "\0" . '%s посетителя по сравнению с предыдущим периодом' . "\0" . '%s посетителей по сравнению с предыдущим периодом','No prior-period data'=>'Нет данных за предыдущий период','new'=>'новое','%1$s vs %2$s in the prior period'=>'%1$s по сравнению с %2$s за предыдущий период','No prior period to compare against yet.'=>'Пока нет предыдущего периода для сравнения.','Pageviews are flat on the same period last year.'=>'Количество просмотров не изменилось по сравнению с тем же периодом прошлого года.','Pageviews are flat on the prior period.'=>'Просмотры не изменились по сравнению с предыдущим периодом.','Pageviews are up %d%%.'=>'Просмотры выросли на %d%%.','Pageviews are down %d%%.'=>'Просмотры упали на %d%%.','Most of the drop is traffic that stopped coming from %s.'=>'Большая часть спада — трафик, который перестал приходить с %s.','Most of the drop is %s.'=>'Большая часть спада — %s.','Most of the rise is new traffic from %s.'=>'Большая часть роста — новый трафик с %s.','Most of the rise is %s.'=>'Большая часть роста — %s.','%1$s took %2$s more of the mix.'=>'%1$s: доля выросла на %2$s.','%1$s lost %2$s of the mix.'=>'%1$s: доля упала на %2$s.','No pageviews were recorded yesterday, but this site was busy the week before. Tracking may have stopped.'=>'Вчера не зафиксировано ни одного просмотра, хотя неделей ранее сайт был активен. Возможно, отслеживание остановилось.','Every visitor is being recorded as Unknown. Countries will stay empty until geo-location is set up.'=>'Все посетители записываются как «Неизвестно». Страны будут пустыми, пока не настроена геолокация.','404 errors are up %1$d%%, mostly on %2$s.'=>'Ошибок 404 стало больше на %1$d%%, в основном на %2$s.','Traffic is down %d%% on the prior period, well beyond normal variation.'=>'Трафик упал на %d%% по сравнению с предыдущим периодом — намного больше обычных колебаний.','Traffic is up %d%% on the prior period, well beyond normal variation.'=>'Трафик вырос на %d%% по сравнению с предыдущим периодом — намного больше обычных колебаний.','Daily'=>'Ежедневно','Weekly'=>'Еженедельно','Monthly'=>'Ежемесячно','month and yearF Y'=>'F Y','[%1$s] Daily Analytics: %2$s'=>'[%1$s] Ежедневная аналитика: %2$s','[%1$s] Monthly Analytics: %2$s'=>'[%1$s] Ежемесячная аналитика: %2$s','[%1$s] Weekly Analytics: %2$s'=>'[%1$s] Еженедельная аналитика: %2$s','no views timed yet'=>'пока нет просмотров с замером времени','Time on page is recorded from this update on. A view reports its time when the reader leaves the page, and the next run of the collector records it, so the first figure appears within a few minutes of the first visit.'=>'Время на странице записывается начиная с этого обновления. Просмотр передаёт своё время, когда посетитель уходит со страницы, а следующий запуск сборщика данных его сохраняет, поэтому первое значение появляется в течение нескольких минут после первого визита.','timed from %s'=>'время учитывается с %s','Time on page has been recorded since %s. This range ends before that, so there is nothing to average.'=>'Время на странице записывается с %s. Этот период заканчивается раньше, поэтому усреднять нечего.','no views timed in this range'=>'в этом периоде нет просмотров с замеренным временем','Time on page has been recorded since %s, but no view in this range has reported a time yet. Views report when the reader leaves the page.'=>'Время на странице записывается с %s, но ни один просмотр в этом периоде пока не передал время. Просмотры передают его, когда посетитель уходит со страницы.','not counted yet'=>'пока не учитывается','Bounce rate starts counting once the update has finished setting up, on the next scheduled run or the next visit to wp-admin.'=>'Показатель отказов начнёт учитываться, когда обновление завершит настройку: при следующем плановом запуске или следующем заходе в wp-admin.','starts counting %s'=>'начнёт учитываться %s','Visitors who arrived before this update were already counted, so bounce rate starts with the first full day, %s.'=>'Посетители, пришедшие до этого обновления, уже были учтены, поэтому показатель отказов начинается с первого полного дня, %s.','counted from %s'=>'учитывается с %s','Bounce rate has been counted since %s. This range ends before that.'=>'Показатель отказов учитывается с %s. Этот период заканчивается раньше.','counted from %s, no visitors yet'=>'учитывается с %s, посетителей пока нет','Bounce rate has been counted since %s. It fills in with the first run of the collector after a visit, within a few minutes.'=>'Показатель отказов учитывается с %s. Он заполняется при первом запуске сборщика данных после визита, в течение нескольких минут.','%ds'=>'%d с','%1$dm %2$02ds'=>'%1$d мин %2$02d с','Event not found.'=>'Событие не найдено.','Event · %s'=>'Событие · %s','Support'=>'Поддержка','Rate Vireo'=>'Оценить Vireo','You do not have permission to do that.'=>'У вас нет прав для этого действия.','Hourly traffic is stored for the whole site, so the chart shows days while a filter is on.'=>'Почасовой трафик хранится для всего сайта, поэтому при включённом фильтре на графике отображаются дни.','Referrers are only recorded per page for posts and pages with an ID, so this page can be filtered on its own but not combined with a source or referrer.'=>'Реферера записываются по страницам только для записей и страниц с ID, поэтому эту страницу можно отфильтровать отдельно, но не вместе с источником или реферером.','device'=>'устройство','country'=>'страна','source'=>'источник','referrer'=>'реферер','page'=>'страница',', '=>', ','Vireo keeps daily totals per dimension, not per visit, so filtering by %s together cannot be answered exactly.'=>'Vireo хранит дневные итоги по каждому измерению, а не по каждому визиту, поэтому точно отфильтровать данные по %s одновременно нельзя.','This breakdown is not stored by %s, so it is not shown while that filter is on.'=>'Эта разбивка не хранится в %s, поэтому при включённом фильтре она не отображается.','The uploads directory is not writable, so the database cannot be saved.'=>'Каталог загрузок недоступен для записи, поэтому базу данных не удаётся сохранить.','Could not download the database: %s'=>'Не удалось загрузить базу данных: %s','The downloaded database was empty.'=>'Загруженная база данных оказалась пустой.','The downloaded database could not be unpacked.'=>'Загруженную базу данных не удалось распаковать.','Could not create the database directory.'=>'Не удалось создать каталог базы данных.','Could not write the database file.'=>'Не удалось записать файл базы данных.','That does not look like a service account key file. It should contain client_email and private_key.'=>'Это не похоже на файл ключа сервисного аккаунта. В нём должны быть поля client_email и private_key.','This server is missing the OpenSSL functions needed to authenticate with Google.'=>'На этом сервере отсутствуют функции OpenSSL, необходимые для аутентификации в Google.','Could not sign the request with that key. Check the key file was pasted whole.'=>'Не удалось подписать запрос этим ключом. Проверьте, что файл ключа вставлен полностью.','Google would not issue an access token for that key.'=>'Google не выдал токен доступа для этого ключа.','The job that records visits is not scheduled'=>'Задача записи посещений не запланирована','Visits are being written to disk but nothing is moving them into your reports. Deactivating and reactivating the plugin will restore it.'=>'Посещения записываются на диск, но ничего не переносит их в отчёты. Деактивация и повторная активация плагина восстановит задачу.','The recording job is scheduled'=>'Задача записи запланирована','WordPress cron is disabled on this site, which is normal on managed hosting: the host runs it externally instead. Recording depends on that continuing to run.'=>'Cron WordPress отключён на этом сайте — это нормально для управляемого хостинга: хостинг запускает его извне. Запись данных зависит от того, что это продолжает работать.','Visits have not been recorded yet'=>'Посещения ещё не записывались','This is expected on a new install. If it persists for more than a few minutes, the recording job is not running.'=>'Это ожидаемо для новой установки. Если это продолжается дольше нескольких минут, задача записи не выполняется.','Visits stopped being recorded'=>'Запись посещений прекратилась','The last successful run was %s ago, and it should run every minute. Anything since then is still on disk and will be counted once this clears.'=>'Последний успешный запуск был %s назад, а должен выполняться каждую минуту. Всё, что произошло с тех пор, остаётся на диске и будет учтено, как только проблема будет устранена.','Visits are being recorded'=>'Посещения записываются','Last run %s ago.'=>'Последний запуск: %s назад.','The database is refusing writes'=>'База данных отклоняет запись','%1$s. %2$d attempts have failed. The database reported: %3$s'=>'%1$s. Не удалось выполнить %2$d попыток. Ответ базы данных: %3$s','no detail recorded'=>'подробности не зафиксированы','Some visits could not be saved'=>'Часть посещений не удалось сохранить','%d batch was set aside after repeated database errors. The visits are still on disk and can be replayed once the cause is fixed.'=>'%d пакет был отложен после повторяющихся ошибок базы данных. Эти посещения остаются на диске и будут повторно обработаны, как только причина будет устранена.' . "\0" . '%d пакета были отложены после повторяющихся ошибок базы данных. Эти посещения остаются на диске и будут повторно обработаны, как только причина будет устранена.' . "\0" . '%d пакетов было отложено после повторяющихся ошибок базы данных. Эти посещения остаются на диске и будут повторно обработаны, как только причина будет устранена.','Visits are piling up without being saved'=>'Посещения накапливаются, не сохраняясь','%1$s is waiting on disk, the oldest of it from %2$s ago. Visits are being captured but are not reaching your reports.'=>'%1$s ожидает на диске, самые старые данные — от %2$s назад. Посещения фиксируются, но не попадают в отчёты.','The data folder is missing'=>'Папка данных отсутствует','Visits cannot be captured at all until it can be created inside wp-content/uploads.'=>'Посещения не могут фиксироваться, пока эта папка не будет создана внутри wp-content/uploads.','The data folder is not writable'=>'В папку данных нельзя записывать','Visits are being discarded as they arrive. Check the folder permissions inside wp-content/uploads.'=>'Посещения отбрасываются по мере поступления. Проверьте права доступа к папке внутри wp-content/uploads.','The data folder is writable'=>'В папку данных можно записывать','The reporting tables are missing'=>'Таблицы отчётов отсутствуют','Deactivating and reactivating the plugin will create them.'=>'Деактивация и повторная активация плагина создаст их.','No visits recorded yet'=>'Посещения ещё не записаны','Expected on a new install, or on a site with no traffic since the plugin was activated.'=>'Ожидаемо для новой установки или сайта без трафика с момента активации плагина.','Nothing has been recorded for a while'=>'Давно ничего не записывалось','The most recent day with any data is %s. On a site with regular traffic this means recording has stopped.'=>'Последний день с какими-либо данными — %s. На сайте с регулярным трафиком это означает, что запись прекратилась.','Reports are up to date'=>'Отчёты актуальны','Most recent data: %s.'=>'Последние данные: %s.','Vireo Analytics is recording visits'=>'Vireo Analytics записывает посещения','Analytics'=>'Аналитика','The recording job is scheduled, ran recently, and your reports are up to date.'=>'Задача записи запланирована, недавно выполнялась, и отчёты актуальны.','Vireo Analytics has stopped recording visits'=>'Vireo Analytics прекратил записывать посещения','Vireo Analytics is recording, with something worth checking'=>'Vireo Analytics записывает данные, но кое-что стоит проверить','Whether visits are currently being captured and written to the database.'=>'Фиксируются ли посещения в данный момент и записываются ли в базу данных.','“%1$s” gained the most, %2$s more view than the week before.'=>'«%1$s» вырос сильнее всех: на %2$s просмотр больше, чем неделей ранее.' . "\0" . '«%1$s» вырос сильнее всех: на %2$s просмотра больше, чем неделей ранее.' . "\0" . '«%1$s» вырос сильнее всех: на %2$s просмотров больше, чем неделей ранее.','%1$s sent visitors for the first time: %2$s views.'=>'%1$s впервые привёл посетителей: %2$s просмотров.','Your best week so far: %1$s pageviews, ahead of the previous best of %2$s.'=>'Лучшая неделя за всё время: %1$s просмотров, больше предыдущего рекорда в %2$s.','The site passed %s pageviews in total.'=>'Сайт преодолел отметку в %s просмотров за всё время.','%1$s passed %2$s views.'=>'%1$s: преодолён порог в %2$s просмотров.','%1$s was the busiest day, with %2$s view.'=>'Самым посещаемым днём стал %1$s: %2$s просмотр.' . "\0" . 'Самым посещаемым днём стал %1$s: %2$s просмотра.' . "\0" . 'Самым посещаемым днём стал %1$s: %2$s просмотров.','Import from Koko Analytics'=>'Импорт из Koko Analytics','Import from Jetpack Stats'=>'Импорт из Jetpack Stats','Import from Google Analytics 4'=>'Импорт из Google Analytics 4','Import from Plausible Analytics'=>'Импорт из Plausible Analytics','Restore a Vireo Analytics backup'=>'Восстановить резервную копию Vireo Analytics','Import from %s'=>'Импорт из %s','Unknown importer.'=>'Неизвестный источник импорта.','Replacing deletes everything Vireo Analytics has recorded here before loading the file. Tick the box to confirm, or choose Merge.'=>'При замене все данные, записанные Vireo Analytics, будут удалены до загрузки файла. Установите флажок для подтверждения или выберите «Объединить».','Choose the backup file to begin.'=>'Выберите файл резервной копии, чтобы начать.','The saved key has been removed.'=>'Сохранённый ключ удалён.','That key file could not be read. Paste the whole JSON file, including the private key.'=>'Не удалось прочитать файл ключа. Вставьте весь файл JSON целиком, включая закрытый ключ.','Paste the service account key file to begin.'=>'Чтобы начать, вставьте файл ключа сервисного аккаунта.','Enter the numeric GA4 property ID.'=>'Введите числовой ID ресурса GA4.','Choose a start date on or before the end date.'=>'Выберите дату начала не позже даты окончания.','You have already imported Google Analytics data covering %s. Importing it again adds those numbers on top of the ones already stored, and that cannot be undone. Narrow the dates to what is missing, or tick the box to import anyway.'=>'Вы уже импортировали данные Google Analytics за %s. Повторный импорт добавит эти цифры к уже сохранённым, и отменить это нельзя. Сузьте диапазон дат до недостающих или отметьте галочку, чтобы импортировать всё равно.','Dates must be in YYYY-MM-DD format.'=>'Даты должны быть в формате ГГГГ-ММ-ДД.','Choose the export file from Plausible to begin.'=>'Выберите файл экспорта из Plausible, чтобы начать.','You have already imported Plausible data covering %s. Importing it again adds those numbers on top of the ones already stored, and that cannot be undone. Narrow the dates to what is missing, or tick the box to import anyway.'=>'Вы уже импортировали данные Plausible за период %s. Повторный импорт добавит эти цифры к уже сохранённым, и отменить это нельзя. Сузьте даты до недостающих или установите флажок, чтобы всё равно выполнить импорт.','All fields are required.'=>'Все поля обязательны.','Invalid Blog URI.'=>'Неверный адрес блога.','You have already imported Jetpack Stats covering %s. Importing it again adds those numbers on top of the ones already stored, and that cannot be undone. Narrow the dates to what is missing, or tick the box to import anyway.'=>'Вы уже импортировали данные Jetpack Stats за период %s. Повторный импорт добавит эти цифры к уже сохранённым, и отменить это нельзя. Сузьте даты до недостающих или установите флажок, чтобы всё равно выполнить импорт.','This import screen is out of date. Reload it and start the import again.'=>'Этот экран импорта устарел. Перезагрузите его и запустите импорт заново.','%s has already been imported. Running it again would count the same history twice, so it needs confirming first. Reload the page to see what was imported.'=>'Импорт из %s уже выполнен. Повторный запуск засчитает одну и ту же историю дважды, поэтому сначала нужно подтверждение. Перезагрузите страницу, чтобы увидеть, что было импортировано.','Imported on %1$s at %2$s: %3$s day of history, %4$s to %5$s, %6$s pageviews.'=>'Импорт выполнен %1$s в %2$s: %3$s день истории, с %4$s по %5$s, просмотров: %6$s.' . "\0" . 'Импорт выполнен %1$s в %2$s: %3$s дня истории, с %4$s по %5$s, просмотров: %6$s.' . "\0" . 'Импорт выполнен %1$s в %2$s: %3$s дней истории, с %4$s по %5$s, просмотров: %6$s.','Imported on %1$s at %2$s, covering %3$s to %4$s.'=>'Импорт выполнен %1$s в %2$s, период: с %3$s по %4$s.','Imported on %1$s at %2$s.'=>'Импорт выполнен %1$s в %2$s.','everything available'=>'всё доступное','Collecting data. Your first pageviews appear within a minute; trends need a day to compare against.'=>'Сбор данных. Первые просмотры страниц появятся в течение минуты; для трендов нужен день для сравнения.','Collecting data, %s view so far. Trends appear once there is a prior day to compare against.'=>'Идёт сбор данных: пока %s просмотр. Тренды появятся, когда будет предыдущий день для сравнения.' . "\0" . 'Идёт сбор данных: пока %s просмотра. Тренды появятся, когда будет предыдущий день для сравнения.' . "\0" . 'Идёт сбор данных: пока %s просмотров. Тренды появятся, когда будет предыдущий день для сравнения.','%1$s Mostly %2$s.'=>'%1$s В основном %2$s.','Steady, %1$s view, in line with the prior period. Top: %2$s.'=>'Без изменений, %1$s просмотр, на уровне предыдущего периода. Топ: %2$s.' . "\0" . 'Без изменений, %1$s просмотра, на уровне предыдущего периода. Топ: %2$s.' . "\0" . 'Без изменений, %1$s просмотров, на уровне предыдущего периода. Топ: %2$s.','Steady, %s view, in line with the prior period.'=>'Без изменений, %s просмотр, на уровне предыдущего периода.' . "\0" . 'Без изменений, %s просмотра, на уровне предыдущего периода.' . "\0" . 'Без изменений, %s просмотров, на уровне предыдущего периода.','Source #%d'=>'Источник №%d','That tool cannot be run on a child site.'=>'Этот инструмент нельзя запустить на дочернем сайте.','This site does not have that tool.'=>'На этом сайте нет такого инструмента.','Only read-only tools can be run on a child site.'=>'На дочернем сайте можно запускать только инструменты, работающие в режиме «только чтение».','The tool input is too large.'=>'Входные данные инструмента слишком велики.','The tool input must be a JSON object.'=>'Входные данные инструмента должны быть JSON-объектом.','Read-only site analytics: traffic, top content, where visitors came from, Google searches, AI assistant traffic, broken links, and what changed since the previous period.'=>'Аналитика сайта только для чтения: трафик, популярный контент, откуда пришли посетители, поисковые запросы в Google, трафик от ИИ-ассистентов, битые ссылки и что изменилось по сравнению с предыдущим периодом.','Revenue, which pages and sources drive sales, campaigns, funnels and real-time visitors need Vireo Pro: https://vireowp.com/pricing/'=>'Для данных о доходе, о том, какие страницы и источники приносят продажи, а также для кампаний, воронок и посетителей в реальном времени нужен Vireo Pro: https://vireowp.com/pricing/','You do not have permission to access this page.'=>'У вас нет прав для доступа к этой странице.','That does not look like a Google API key. It is a single line of letters, numbers, dashes and underscores, usually starting with AIza.'=>'Это не похоже на ключ Google API. Ключ состоит из одной строки букв, цифр, дефисов и подчёркиваний и обычно начинается с AIza.','That is not a page address PageSpeed can test.'=>'Этот адрес страницы нельзя проверить в PageSpeed.','Only pages on this site can be tested.'=>'Можно проверять только страницы этого сайта.','PageSpeed can only test pages anyone can open. Publish this post first.'=>'PageSpeed может проверять только страницы, которые открываются для всех. Сначала опубликуйте эту запись.','PageSpeed tests need a Google API key. An administrator can add one under Settings, Search Console & API.'=>'Для тестов PageSpeed нужен ключ Google API. Администратор может добавить его в разделе «Настройки», «Search Console и API».','A test of this page is already running. Its result shows here when it finishes.'=>'Тест этой страницы уже выполняется. Результат появится здесь, когда он завершится.','Google did not answer within a minute. Slow pages can take that long. Try again.'=>'Google не ответил за минуту. Медленным страницам может понадобиться столько времени. Повторите попытку.','Could not reach Google: %s'=>'Не удалось связаться с Google: %s','PageSpeed runs on Google\'s servers, which cannot reach a site that is only on your computer or private network.'=>'PageSpeed работает на серверах Google, а они не могут получить доступ к сайту, который находится только на вашем компьютере или в частной сети.','Google\'s limit for PageSpeed tests on this API key is used up for now. Try again later, or raise the quota in Google Cloud.'=>'Лимит Google на тесты PageSpeed для этого ключа API пока исчерпан. Повторите попытку позже или увеличьте квоту в Google Cloud.','Google rejected the API key. Check it under Settings, Search Console & API.'=>'Google отклонил ключ API. Проверьте его в разделе «Настройки», «Search Console и API».','Google refused the request. Check that the PageSpeed Insights API is enabled in the key\'s Google Cloud project and that the key\'s restrictions allow it.'=>'Google отклонил запрос. Убедитесь, что API PageSpeed Insights включён в проекте Google Cloud, к которому относится ключ, и что ограничения ключа это разрешают.','Google\'s test could not load this page. Check that it is public and opens for logged-out visitors.'=>'Тест Google не смог загрузить эту страницу. Убедитесь, что она общедоступна и открывается для незалогиненных посетителей.','PageSpeed Insights sent back a result this version of Vireo cannot read.'=>'PageSpeed Insights вернул результат, который эта версия Vireo не может прочитать.','PageSpeed Insights returned an error (HTTP %d). Try again in a few minutes.'=>'PageSpeed Insights вернул ошибку (HTTP %d). Повторите попытку через несколько минут.','Blocking time'=>'Время блокировки','First content'=>'Первый контент','The lab stand-in for response to clicks. A test cannot click, so it measures how long the page was too busy to respond.'=>'Лабораторный аналог отклика на клики. Тест не может кликать, поэтому он измеряет, как долго страница была слишком занята, чтобы отвечать.','How long until anything appeared.'=>'Сколько времени прошло, пока что-либо появилось.','Up to %s faster'=>'До %s быстрее','Less layout shift'=>'Меньше смещений макета','You are not allowed to run page tests.'=>'У вас нет прав на запуск тестов страниц.','Popular posts (Vireo)'=>'Популярные записи (Vireo)','Your most viewed posts, from Vireo Analytics.'=>'Самые просматриваемые записи по данным Vireo Analytics.','Popular posts'=>'Популярные записи','Last 7 days'=>'Последние 7 дней','Last 30 days'=>'Последние 30 дней','Last 90 days'=>'Последние 90 дней','All time'=>'За всё время','Title:'=>'Заголовок:','Number of posts:'=>'Количество записей:','Period:'=>'Период:','Post types:'=>'Типы записей:','Display:'=>'Отображение:','List'=>'Список','List with featured images'=>'Список с миниатюрами записей','Show view counts'=>'Показывать количество просмотров','Leave out the post being viewed'=>'Не показывать текущую запись','%s view'=>'%s просмотр' . "\0" . '%s просмотра' . "\0" . '%s просмотров','No popular posts yet. They appear here once Vireo has recorded views for published posts in this period.'=>'Популярных записей пока нет. Они появятся здесь, когда Vireo зафиксирует просмотры опубликованных записей за этот период.','Views (30d)'=>'Просмотры (30 дн.)','%s in 30 days'=>'%s за 30 дней','Post stats · %s'=>'Статистика записи · %s','Referrer not specified.'=>'Источник перехода не указан.','Referrer · %s'=>'Источник перехода · %s','Invalid start or end date.'=>'Неверная дата начала или окончания.','end must be on or after start.'=>'дата окончания должна быть не раньше даты начала.','Goal not found.'=>'Цель не найдена.','180 days'=>'180 дней','1 year'=>'1 год','2 years'=>'2 года','5 years'=>'5 лет','Never purge'=>'Не удалять','Give the view a name.'=>'Укажите название для этого вида.','You can keep up to %d saved views. Delete one to save another.'=>'Можно сохранить не более %d видов. Удалите один, чтобы сохранить другой.','Enter the property exactly as Search Console shows it, either a URL or sc-domain:example.com.'=>'Введите ресурс точно так, как он указан в Search Console: либо URL, либо sc-domain:example.com.','Search Console is not connected yet.'=>'Search Console пока не подключён.','Could not store the data for %s. Nothing was lost; run the sync again.'=>'Не удалось сохранить данные за %s. Ничего не потеряно; запустите синхронизацию ещё раз.','Google refused the request. Check the service account has access to this Search Console property.'=>'Google отклонил запрос. Проверьте, что у сервисного аккаунта есть доступ к этому ресурсу Search Console.','Search Console has no property with that address. Copy it exactly as it appears there.'=>'В Search Console нет ресурса с таким адресом. Скопируйте его точно так, как он указан там.','Search Console returned an unexpected response (HTTP %d).'=>'Search Console вернул неожиданный ответ (HTTP %d).','Search Console returned a response we could not read.'=>'Search Console вернул ответ, который не удалось прочитать.','General'=>'Общие','Tracking'=>'Отслеживание','Email digest'=>'Дайджест по email','Search Console & API'=>'Search Console и API','Import & export'=>'Импорт и экспорт','Vireo Analytics Settings'=>'Настройки Vireo Analytics','Settings'=>'Настройки','Settings saved.'=>'Настройки сохранены.','Vireo Analytics:'=>'Vireo Analytics:','Geo-location database is missing. Countries will show as unknown until you install it.'=>'База данных геолокации отсутствует. Страны будут отображаться как неизвестные, пока вы её не установите.','Setup instructions'=>'Инструкции по настройке','Nothing was removed. Type the site\'s name exactly as shown to confirm.'=>'Ничего не удалено. Введите название сайта точно так, как оно показано, чтобы подтвердить удаление.','Filtered as bot.'=>'Отфильтровано как бот.','Empty User-Agent is treated as a bot by Bot_Filter::is_bot_request.'=>'Пустой User-Agent считается ботом в Bot_Filter::is_bot_request.','Filtered as bot. This request would NOT be tracked.'=>'Отфильтровано как бот. Этот запрос НЕ будет отслеживаться.','Would be tracked. This request passes the bot filter.'=>'Будет отслеживаться. Этот запрос проходит фильтр ботов.','Matched the bot-UA pattern: %s'=>'Совпадение с шаблоном UA бота: %s','Matched via heuristic (e.g. empty UA) rather than the UA regex.'=>'Совпадение по эвристике (например, пустой UA), а не по регулярному выражению UA.','No bot-UA pattern matched, and no Cloudflare bot signals would fire for a typical request.'=>'Ни один шаблон UA бота не совпал, и для обычного запроса не сработали бы сигналы ботов Cloudflare.','The front-end address was not saved. Enter the full address of the site, starting with http:// or https://, for example https://www.example.com.'=>'Адрес фронтенда не сохранён. Введите полный адрес сайта, начиная с http:// или https://, например https://www.example.com.','Give the site a name.'=>'Укажите название сайта.','Enter the full address of the site, starting with http:// or https://, for example https://www.example.com.'=>'Введите полный адрес сайта, начиная с http:// или https://, например https://www.example.com.','This install has reached its number of connected sites.'=>'Достигнуто максимальное число подключённых сайтов для этой установки.','That address is already connected.'=>'Этот адрес уже подключён.','That address is set as the headless front end. A site is either the front end for this WordPress site or a connected site with its own numbers, not both.'=>'Этот адрес задан как headless-фронтенд. Сайт может быть либо фронтендом для этого сайта WordPress, либо подключённым сайтом с собственной статистикой, но не тем и другим одновременно.','That is this site\'s own address. Its pages are already counted.'=>'Это адрес самого этого сайта. Его страницы уже учитываются.','%ss'=>'%s с','%sms'=>'%s мс','Load time'=>'Время загрузки','Response to clicks'=>'Отклик на клики','Layout shift'=>'Смещение макета','Good'=>'Хорошо','Needs work'=>'Требует улучшения','Poor'=>'Плохо','How long until the main content appeared.'=>'Сколько времени прошло до появления основного контента.','How long the page took to respond when someone interacted with it.'=>'Сколько времени страница отвечала на взаимодействие пользователя.','How much the page moved around while it loaded.'=>'Насколько сильно страница смещалась во время загрузки.','%1$s to %2$s'=>'с %1$s по %2$s','%1$s: imported from %2$s.'=>'%1$s: импортировано из %2$s.','%1$s: partly imported from %2$s, partly counted by Vireo Analytics.'=>'%1$s: частично импортировано из %2$s, частично посчитано Vireo Analytics.','%s: counted by Vireo Analytics.'=>'%s: посчитано Vireo Analytics.','%1$s in %2$s so far'=>'%1$s за %2$s на данный момент','%1$s in %2$s'=>'%1$s за %2$s','%s pageview.'=>'%s просмотр.' . "\0" . '%s просмотра.' . "\0" . '%s просмотров.','%1$s pageviews, %2$s on the same stretch of %3$s.'=>'Просмотров: %1$s, за такой же период %3$s: %2$s.','%1$s pageviews, %2$s on %3$s.'=>'Просмотров: %1$s, за %3$s: %2$s.','Busiest month: %1$s. Busiest day: %2$s, with %3$s pageviews.'=>'Самый активный месяц: %1$s. Самый активный день: %2$s, просмотров: %3$s.','Top page: %1$s (%2$s pageviews).'=>'Топ-страница: %1$s (просмотров: %2$s).','Top referrer: %1$s (%2$s pageviews).'=>'Топ-источник переходов: %1$s (просмотров: %2$s).','Top country: %s.'=>'Топ-страна: %s.','Includes history imported from %s.'=>'Включает историю, импортированную из %s.','Home page and archives (imported)'=>'Главная страница и архивы (импортировано)','Google app'=>'Приложение Google','short date with yearM j, Y'=>'j M Y','short date without yearM j'=>'j M','Today'=>'Сегодня','Yesterday'=>'Вчера','Last 7'=>'7 дней','Last 14'=>'14 дней','Last 30'=>'30 дней','Last 90'=>'90 дней','This month'=>'Этот месяц','Last month'=>'Прошлый месяц','YTD'=>'С начала года','Not shown with these filters'=>'Не отображается при этих фильтрах','Previous period'=>'Предыдущий период','Same period last year'=>'Тот же период в прошлом году','Device is %s'=>'Устройство: %s','Country is %s'=>'Страна: %s','Source is %s'=>'Источник: %s','Referrer is %s'=>'Реферер: %s','Page is %s'=>'Страница: %s','Vireo keeps daily totals per dimension, so this cannot be combined with the filters already on.'=>'Vireo хранит ежедневные итоги по каждому измерению, поэтому это нельзя сочетать с уже включёнными фильтрами.','Site'=>'Сайт','This site'=>'Этот сайт','Switch'=>'Переключить','This link asked for a view that has expired, so the default range is shown instead. Dashboard links stop working after about a day. Pick a range below to carry on.'=>'Эта ссылка запрашивала представление, срок действия которого истёк, поэтому показан диапазон по умолчанию. Ссылки на панель перестают работать примерно через сутки. Выберите диапазон ниже, чтобы продолжить.','All devices'=>'Все устройства','All sources'=>'Все источники','All countries'=>'Все страны','Filter:'=>'Фильтр:','Device'=>'Устройство','Country'=>'Страна','Source'=>'Источник','Apply'=>'Применить','Remove this filter'=>'Убрать этот фильтр','Clear all'=>'Сбросить всё','Saved views'=>'Сохранённые виды','Saved views…'=>'Сохранённые виды…','Forget view'=>'Удалить вид','Save view'=>'Сохранить вид','View name'=>'Название вида','Name this view'=>'Назовите этот вид','Save'=>'Сохранить','Cancel'=>'Отмена','Clear the filters'=>'Сбросить фильтры','Filters apply to the Overview tab.'=>'Фильтры применяются на вкладке «Обзор».','Date range'=>'Диапазон дат','Custom'=>'Произвольный','Year in review'=>'Итоги года','Print / Save as PDF'=>'Печать / Сохранить как PDF','Compare'=>'Сравнить','Compare with'=>'Сравнить с','Start'=>'Начало','End'=>'Конец','Move %s. Drag, or focus and use the arrow keys.'=>'Переместить %s. Перетащите или используйте клавиши со стрелками после фокуса.','Reset layout'=>'Сбросить расположение','Report sections'=>'Разделы отчёта','Loading the backup of %1$s, %2$s to %3$s, %4$s rows. %5$s'=>'Загрузка резервной копии %1$s, %2$s — %3$s, строк: %4$s. %5$s','Everything recorded here is deleted first.'=>'Всё, что записано здесь, сначала удаляется.','Days in the file replace the same days here; everything else is kept.'=>'Дни из файла заменяют те же дни здесь, всё остальное сохраняется.','Loads a file made with Download backup on another install, or on this one. Everything the reports are built from comes across: daily totals, pages, referrers, countries, devices, events, missing pages, bot traffic, Core Web Vitals, chart notes and the Search Console cache. Settings and connected sites are not in the file.'=>'Загружает файл, созданный функцией «Скачать резервную копию» на другой установке или на этой же. Переносится всё, на чём строятся отчёты: суточные итоги, страницы, реферреры, страны, устройства, события, отсутствующие страницы, трафик ботов, Core Web Vitals, заметки на графиках и кэш Search Console. Настройки и подключённые сайты в файл не входят.','To make the file, open %s on the site you are copying from and use Download backup.'=>'Чтобы создать файл, откройте %s на сайте, с которого копируете данные, и нажмите «Скачать резервную копию».','Settings, Import & export'=>'Настройки, Импорт и экспорт','Backup file (.jsonl.gz or .jsonl)'=>'Файл резервной копии (.jsonl.gz или .jsonl)','Maximum upload size: %s.'=>'Максимальный размер загружаемого файла: %s.','What to do with the numbers already here'=>'Что делать с уже имеющимися здесь данными','Merge: days in the file replace the same days here, everything else is kept.'=>'Объединить: дни из файла заменяют те же дни здесь, всё остальное сохраняется.','Replace: delete everything recorded here first, so this site ends up holding exactly what the file holds.'=>'Заменить: сначала удалить всё, что записано здесь, чтобы на сайте остались ровно те данные, что есть в файле.','Replace deletes every report table on this site before loading the file, and that cannot be undone. Download a backup of this site first if there is anything here you might want back.'=>'Режим «Заменить» удаляет все таблицы отчётов на этом сайте перед загрузкой файла, и это нельзя отменить. Если здесь есть данные, которые вам могут понадобиться, сначала скачайте резервную копию этого сайта.','I understand that everything recorded here will be deleted.'=>'Я понимаю, что всё записанное здесь будет удалено.','Loading the same file twice gives the same numbers, so a restore that stopped partway can simply be run again.'=>'Повторная загрузка того же файла даёт те же цифры, поэтому прерванное восстановление можно просто запустить снова.','Earlier restores'=>'Предыдущие восстановления','Restore'=>'Восстановить','Restore progress'=>'Ход восстановления','View your reports'=>'Перейти к отчётам','%s history imported'=>'История из %s импортирована','It is part of your Vireo Analytics reports now. Imports cannot be undone, and running this one again would add the same history a second time.'=>'Теперь она входит в ваши отчёты Vireo Analytics. Импорт нельзя отменить, а повторный запуск добавит ту же историю во второй раз.','Go to Plugins'=>'Перейти к плагинам','This server is missing the OpenSSL functions needed to authenticate with Google. Ask your host to enable the PHP openssl extension.'=>'На этом сервере отсутствуют функции OpenSSL, необходимые для аутентификации в Google. Попросите хостинг включить расширение PHP openssl.','Brings across daily pageviews and visitors, your pages, referrers, which pages each referrer sent readers to, countries, devices, outbound clicks, downloads, form submissions and your own custom events. Everything is stored in your own database, the same as traffic recorded from here on.'=>'Переносит ежедневные просмотры и посетителей, ваши страницы, источники переходов, страницы, на которые каждый источник привёл читателей, страны, устройства, переходы по внешним ссылкам, загрузки, отправки форм и ваши собственные события. Всё хранится в вашей базе данных, так же как и трафик, записанный с этого момента.','How to get the key file'=>'Как получить файл ключа','In Google Cloud Console'=>'В Google Cloud Console','Create a project, or open one you already have.'=>'Создайте проект или откройте уже существующий.','Under APIs and services, enable the Google Analytics Data API. The plain Analytics API is a different one and will not work.'=>'В разделе «API и сервисы» включите Google Analytics Data API. Обычный Analytics API — это другой API, он не подойдёт.','Under IAM and admin, then Service accounts, create a service account. Its address ends in .iam.gserviceaccount.com, and you need that address for the next part.'=>'В разделе «IAM и администрирование» → «Сервисные аккаунты» создайте сервисный аккаунт. Его адрес заканчивается на .iam.gserviceaccount.com, и он понадобится для следующего шага.','Open the service account, go to Keys, add a key, and choose JSON. The file downloads once and Google will not give it to you again.'=>'Откройте сервисный аккаунт, перейдите в «Ключи», добавьте ключ и выберите JSON. Файл скачивается один раз, повторно Google его не выдаст.','In Google Analytics'=>'В Google Analytics','Open Admin, then Property access management, and add the service account address with Viewer access. Grant it on the property you want to import, not on the account.'=>'Откройте «Админ» → «Управление доступом к ресурсу» и добавьте адрес сервисного аккаунта с доступом на просмотр (Viewer). Выдайте доступ именно на нужный ресурс, а не на весь аккаунт.','Your property ID is the number under Admin, then Property details. It is digits only, not the G- measurement ID.'=>'ID ресурса — это число в разделе «Админ» → «Сведения о ресурсе». Это только цифры, не идентификатор измерения, начинающийся с G-.','Then open the downloaded file in a text editor and paste all of it, braces included, into the box below. The key stays in your database and is only used to ask Google for your own data. It is never sent anywhere else.'=>'Затем откройте скачанный файл в текстовом редакторе и вставьте его целиком, включая фигурные скобки, в поле ниже. Ключ хранится в вашей базе данных и используется только для запроса ваших собственных данных у Google. Больше никуда он не отправляется.','Service account key (JSON)'=>'Ключ сервисного аккаунта (JSON)','A key is saved. Leave this empty to keep it.'=>'Ключ уже сохранён. Оставьте поле пустым, чтобы сохранить его.','Using %s. Grant that address Viewer access on the property.'=>'Используется %s. Выдайте этому адресу доступ на просмотр (Viewer) к ресурсу.','Property ID'=>'ID ресурса','Start date'=>'Дата начала','End date'=>'Дата окончания','Importing the same dates twice adds the numbers twice, and that cannot be undone. If a run stops partway, narrow the range to what is missing rather than starting again from the beginning.'=>'Повторный импорт тех же дат удвоит цифры, и отменить это нельзя. Если импорт прервался, сузьте диапазон до недостающего вместо повторного запуска с начала.','Already imported'=>'Уже импортировано','Import these dates again anyway, adding to what is already stored.'=>'Всё равно импортировать эти даты снова, добавив к уже сохранённым.','Start import'=>'Начать импорт','Import progress'=>'Ход импорта','Remove the saved key'=>'Удалить сохранённый ключ','The key is only needed while importing. Removing it does not affect data already brought across.'=>'Ключ нужен только во время импорта. Его удаление не повлияет на уже перенесённые данные.','No %s data found in this database. The plugin needs to have been installed on this site and collected some data before there is anything to bring across.'=>'В этой базе данных не найдены данные %s. Чтобы было что переносить, плагин должен быть установлен на этом сайте и успеть собрать данные.','Back to import & export'=>'Назад к импорту и экспорту','Records found'=>'Найдено записей','What this does:'=>'Что это делает:','Copies your history from %s into Vireo Analytics. The source data is read only and is never modified.'=>'Копирует вашу историю из %s в Vireo Analytics. Исходные данные только читаются и никогда не изменяются.','Run it once.'=>'Запускайте один раз.','An import adds what it reads to what Vireo Analytics already holds, so a second run would count the same history twice. Imports cannot be undone.'=>'Импорт добавляет прочитанное к данным, которые уже хранятся в Vireo Analytics, поэтому повторный запуск засчитает ту же историю дважды. Импорт нельзя отменить.','Import again anyway'=>'Всё равно импортировать снова','Only if Vireo Analytics no longer holds the history from %s, for example after its data was reset. Otherwise every day imported above is counted twice, and there is no way to take it back out.'=>'Только если в Vireo Analytics больше нет истории из %s, например после сброса данных. Иначе каждый импортированный выше день будет засчитан дважды, и убрать это будет нельзя.','I understand this adds the same history a second time.'=>'Я понимаю, что это добавит ту же историю во второй раз.','Import again'=>'Импортировать снова','You can deactivate %s whenever you are ready. Vireo Analytics is tracking on its own now.'=>'Вы можете деактивировать %s, когда будете готовы. Vireo Analytics теперь ведёт отслеживание самостоятельно.','Jetpack isn\'t active here, so the import uses your WordPress.com API key.'=>'Jetpack здесь не активен, поэтому импорт использует ваш API-ключ WordPress.com.','Pulls daily pageviews and referrers from the Jetpack / WordPress.com stats API. Country and device data isn\'t available in this API — Vireo Analytics will start tracking those from installation onward.'=>'Загружает ежедневные просмотры и источники переходов из API статистики Jetpack / WordPress.com. Данные о странах и устройствах в этом API недоступны — Vireo Analytics начнёт отслеживать их с момента установки.','Jetpack Stats has no visitor counts, so imported days show pageviews only.'=>'В Jetpack Stats нет данных о посетителях, поэтому для импортированных дней показываются только просмотры.','WordPress.com API key'=>'Ключ API WordPress.com','A key is saved for this import — leave blank to reuse it'=>'Для этого импорта сохранён ключ — оставьте поле пустым, чтобы использовать его снова','Find this under <strong>Jetpack → Settings → Security → Akismet</strong>, or in your WordPress.com account under <strong>Security → Application Passwords</strong>.'=>'Найдите его в разделе <strong>Jetpack → Настройки → Безопасность → Akismet</strong> или в аккаунте WordPress.com в разделе <strong>Безопасность → Пароли приложений</strong>.','Blog URI'=>'Адрес блога','The domain Jetpack is tracking. Usually your site\'s host.'=>'Домен, который отслеживает Jetpack. Обычно это хост вашего сайта.','Re-running is additive.'=>'Повторный запуск суммирует данные.','Running the import over an overlapping date range will double-count those days.'=>'Запуск импорта на пересекающемся диапазоне дат приведёт к двойному подсчёту этих дней.','No Koko Analytics data found in this database. If you just activated Koko Analytics, let it collect some pageviews first and come back.'=>'В этой базе данных не найдены данные Koko Analytics. Если вы только что активировали Koko Analytics, дайте ему сначала собрать немного просмотров и вернитесь.','Days of data'=>'Дней данных','Copies Koko\'s daily rollups into Vireo Analytics\'s tables. Koko\'s data is not modified.'=>'Копирует ежедневные сводки Koko в таблицы Vireo Analytics. Данные Koko не изменяются.','Pageviews, visitors, pages and referrers come across. Countries, devices and events from Koko Analytics Pro are not imported.'=>'Просмотры, посетители, страницы и источники переходов переносятся. Страны, устройства и события из Koko Analytics Pro не импортируются.','Only if Vireo Analytics no longer holds the history from Koko Analytics, for example after its data was reset. Otherwise every day imported above is counted twice, and there is no way to take it back out.'=>'Только если в Vireo Analytics больше нет истории из Koko Analytics, например после сброса данных. Иначе каждый импортированный выше день будет засчитан дважды, и убрать это будет нельзя.','You can deactivate Koko Analytics from the Plugins screen when you\'re ready. Vireo Analytics is tracking on its own now.'=>'Вы можете деактивировать Koko Analytics на экране «Плагины», когда будете готовы. Vireo Analytics теперь ведёт отслеживание самостоятельно.','Dismiss'=>'Скрыть','Welcome to Vireo Analytics.'=>'Добро пожаловать в Vireo Analytics.','We found Koko Analytics here with %d day of data. Bring it across in one click, rather than starting at zero.'=>'Мы нашли здесь Koko Analytics с %d днём данных. Перенесите их в один клик, а не начинайте с нуля.' . "\0" . 'Мы нашли здесь Koko Analytics с %d днями данных. Перенесите их в один клик, а не начинайте с нуля.' . "\0" . 'Мы нашли здесь Koko Analytics с %d днями данных. Перенесите их в один клик, а не начинайте с нуля.','We found %s on this site. Import that history so your numbers do not start at zero. Your existing data is read only and is never changed.'=>'На этом сайте найдено: %s. Импортируйте эту историю, чтобы ваша статистика не начиналась с нуля. Существующие данные только читаются и никогда не изменяются.','Start fresh'=>'Начать с нуля','Vireo Analytics has its own data from %1$s, so the import stops on %2$s. Days from %1$s on keep the counts Vireo recorded.'=>'У Vireo Analytics есть собственные данные с %1$s, поэтому импорт заканчивается %2$s. Для дней начиная с %1$s сохраняются значения, записанные Vireo.','Also import %s onwards. Those days already hold what Vireo counted, so the imported numbers are added on top and the days are counted twice.'=>'Также импортировать данные начиная с %s. В эти дни уже есть данные, подсчитанные Vireo, поэтому импортированные числа сложатся с ними, и дни будут посчитаны дважды.','daily visitors and pageviews'=>'ежедневные посетители и просмотры','device types'=>'типы устройств','entry pages'=>'страницы входа','exit pages'=>'страницы выхода','browsers'=>'браузеры','operating systems'=>'операционные системы','goals and custom events'=>'цели и пользовательские события','custom properties'=>'пользовательские свойства','referrers, which this export names without their addresses'=>'источники переходов, которые в этом экспорте указаны без адресов','Importing %1$s to %2$s: %3$s.'=>'Импорт за период с %1$s по %2$s: %3$s.','Not imported, because Vireo Analytics has nowhere to keep them: %s.'=>'Не импортировано, так как в Vireo Analytics их негде хранить: %s.','Import another export'=>'Импортировать другой экспорт','For an export covering dates not imported yet. Dates already imported are refused unless you confirm them below.'=>'Для экспорта, охватывающего даты, которые ещё не импортированы. Уже импортированные даты отклоняются, если вы не подтвердите их ниже.','Brings across daily pageviews and visitors, your pages, referrers, countries, device types, and goals and custom events from a Plausible export. Outbound link clicks, file downloads and form submissions become the same events Vireo Analytics records itself, and 404 events are listed under missing pages. Browsers and operating systems are not imported: Plausible exports them separately from device type, and Vireo Analytics stores the three together, so for imported days they show as Unknown.'=>'Переносит ежедневные просмотры и посетителей, ваши страницы, источники переходов, страны, типы устройств, а также цели и пользовательские события из экспорта Plausible. Клики по внешним ссылкам, загрузки файлов и отправки форм становятся теми же событиями, которые записывает сам Vireo Analytics, а события 404 показываются в списке отсутствующих страниц. Браузеры и операционные системы не импортируются: Plausible экспортирует их отдельно от типа устройства, а Vireo Analytics хранит все три вместе, поэтому для импортированных дней они отображаются как «Неизвестно».','How to get the export'=>'Как получить экспорт','In Plausible, open the site, then Site settings, then Imports & Exports.'=>'В Plausible откройте сайт, затем «Site settings», затем «Imports & Exports».','Under Export data, start an export. Plausible emails a link to a zip file when it is ready.'=>'В разделе «Export data» запустите экспорт. Когда файл будет готов, Plausible пришлёт ссылку на zip-архив по электронной почте.','Download the zip and upload it here as it is. If you have already unzipped it, select the CSV files instead.'=>'Скачайте zip-архив и загрузите его сюда как есть. Если вы уже распаковали его, выберите CSV-файлы.','The file is read once and deleted. Nothing is sent to Plausible and no account details are needed.'=>'Файл читается один раз и удаляется. Ничего не отправляется в Plausible, данные учётной записи не нужны.','Plausible export (.zip or .csv files)'=>'Экспорт Plausible (файлы .zip или .csv)','Optional. Leave both empty to import every day in the export.'=>'Необязательно. Оставьте оба поля пустыми, чтобы импортировать все дни из экспорта.','Importing the same dates twice adds the numbers twice, and that cannot be undone. If a run stops partway, set the dates to what is missing rather than starting again from the beginning.'=>'Повторный импорт тех же дат удваивает числа, и это нельзя отменить. Если процесс прервался на середине, укажите даты, которых не хватает, а не начинайте сначала.','Analytics across the network'=>'Аналитика по всей сети','Last %d day'=>'Последний %d день' . "\0" . 'Последние %d дня' . "\0" . 'Последние %d дней','Refresh'=>'Обновить','This network has more sites than one page can query. Showing the first %1$s of %2$s.'=>'В этой сети больше сайтов, чем можно запросить на одной странице. Показаны первые %1$s из %2$s.','No site on the network has recorded anything yet.'=>'Ни один сайт сети ещё ничего не записал.','%1$s and %2$s across %3$s, %4$s to %5$s.'=>'%1$s и %2$s по %3$s, с %4$s по %5$s.','%s pageview'=>'%s просмотр' . "\0" . '%s просмотра' . "\0" . '%s просмотров','%s visitor'=>'%s посетитель' . "\0" . '%s посетителя' . "\0" . '%s посетителей','%s site'=>'%s сайт' . "\0" . '%s сайта' . "\0" . '%s сайтов','Open'=>'Открыть','Totals are cached for fifteen minutes, since each one is a separate query against that site.'=>'Итоги кэшируются на пятнадцать минут, поскольку каждый из них — отдельный запрос к соответствующему сайту.','Monday'=>'Понедельник','Tuesday'=>'Вторник','Wednesday'=>'Среда','Thursday'=>'Четверг','Friday'=>'Пятница','Saturday'=>'Суббота','Sunday'=>'Воскресенье','WordPress handed the test email for %s to your server\'s mail system.'=>'WordPress передал тестовое письмо для %s почтовой системе вашего сервера.','If it has not arrived within a few minutes, check your spam folder. If it is not there either, your host is not delivering mail sent from WordPress, which affects password resets and every other email the site sends. An SMTP plugin such as WP Mail SMTP or FluentSMTP usually fixes it.'=>'Если письмо не пришло в течение нескольких минут, проверьте папку «Спам». Если его нет и там, ваш хостинг не доставляет письма, отправленные из WordPress, а это касается и сброса паролей, и всех остальных писем сайта. Обычно проблему решает SMTP-плагин, например WP Mail SMTP или FluentSMTP.','WordPress could not send the test email to %s.'=>'WordPress не смог отправить тестовое письмо на адрес %s.','The mail system said: %s'=>'Ответ почтовой системы: %s','This is a problem with how the site sends mail, not with the digest. An SMTP plugin such as WP Mail SMTP or FluentSMTP usually fixes it.'=>'Проблема в том, как сайт отправляет почту, а не в дайджесте. Обычно её решает SMTP-плагин, например WP Mail SMTP или FluentSMTP.','Email reports class is not loaded.'=>'Класс отчётов по электронной почте не загружен.','Country database installed. Countries will resolve from now on.'=>'База данных стран установлена. Страны теперь будут определяться.','The country database could not be installed.'=>'Не удалось установить базу данных стран.','Site connected. Paste its tag into the site and its visits will start showing on the dashboard.'=>'Сайт подключён. Вставьте его тег на сайт, и посещения начнут отображаться на панели.','Site removed, along with everything recorded for it.'=>'Сайт удалён вместе со всеми записанными для него данными.','That did not work.'=>'Не получилось.','%s stored day removed from the countries report.'=>'Из отчёта по странам удалён %s сохранённый день.' . "\0" . 'Из отчёта по странам удалено %s сохранённых дня.' . "\0" . 'Из отчёта по странам удалено %s сохранённых дней.','Settings sections'=>'Разделы настроек','Do not count'=>'Не учитывать','Roles whose visits are not counted'=>'Роли, визиты которых не учитываются','Visits from people logged in with a ticked role are left out of every report. Administrators are ticked by default so your own browsing does not pollute the stats; tick editors, authors or shop managers to leave out the rest of the team.'=>'Визиты авторизованных пользователей с отмеченной ролью исключаются из всех отчётов. Администраторы отмечены по умолчанию, чтобы ваша собственная активность не искажала статистику; отметьте редакторов, авторов или менеджеров магазина, чтобы исключить и остальную команду.','Toolbar'=>'Панель инструментов','Show today\'s pageviews in the admin toolbar.'=>'Показывать сегодняшние просмотры страниц в панели инструментов администратора.','Data retention'=>'Хранение данных','Custom (%d day)'=>'Произвольный (%d день)' . "\0" . 'Произвольный (%d дня)' . "\0" . 'Произвольный (%d дней)','Rows in daily rollup tables older than this are purged by a daily cron job.'=>'Строки в таблицах ежедневных сводок старше этого срока удаляются ежедневным заданием cron.','Current usage: %1$s MB across %2$d analytics table.'=>'Текущий объём: %1$s МБ в %2$d таблице аналитики.' . "\0" . 'Текущий объём: %1$s МБ в %2$d таблицах аналитики.' . "\0" . 'Текущий объём: %1$s МБ в %2$d таблицах аналитики.','Who can see the numbers'=>'Кто видит цифры','Roles with access'=>'Роли с доступом','Roles that can view analytics'=>'Роли, которым доступна аналитика','Administrator'=>'Администратор','(always)'=>'(всегда)','Administrators can always read the dashboard. This cannot be changed.'=>'Администраторы всегда могут просматривать панель. Это нельзя изменить.','Lets someone read the dashboard without making them an administrator. Changing settings, running imports and everything destructive still needs full administrator rights.'=>'Позволяет просматривать панель, не делая пользователя администратором. Изменение настроек, запуск импорта и любые деструктивные действия по-прежнему требуют полных прав администратора.','Headless front end'=>'Headless-фронтенд','If this WordPress site is only the editor and another site (Astro, Next.js, anything else) shows the pages to readers, enter that site\'s address. Its pages can then send pageviews here, and each one is matched to the WordPress post it shows.'=>'Если этот сайт WordPress служит только редактором, а страницы читателям показывает другой сайт (Astro, Next.js или любой другой), укажите адрес этого сайта. Тогда его страницы смогут отправлять сюда просмотры, и каждый просмотр будет сопоставляться с записью WordPress, которую он показывает.','Front-end site address'=>'Адрес сайта-фронтенда','The address readers see in their browser, including https://. One site; pageviews sent from any other address are refused. Leave empty if this WordPress site serves its own pages.'=>'Адрес, который читатели видят в браузере, включая https://. Только один сайт; просмотры, отправленные с любого другого адреса, отклоняются. Оставьте поле пустым, если этот сайт WordPress сам показывает свои страницы.','Add to the front end'=>'Добавить на фронтенд','Paste this before </body> on every page. Pages that know their WordPress post can add <meta name="vireo:post-id" content="123">; for a site that changes pages without reloading, add data-spa="history" to the tag.'=>'Вставьте это перед </body> на каждой странице. Страницы, которым известна их запись WordPress, могут добавить <meta name="vireo:post-id" content="123">; для сайта, который меняет страницы без перезагрузки, добавьте в тег data-spa="history".','Pageviews are sent to %s. Pages are matched to posts by their path, so a front end that keeps the WordPress permalink structure needs nothing else; the vireo_headless_post_id filter maps anything that differs.'=>'Просмотры отправляются на %s. Страницы сопоставляются с записями по их пути, поэтому фронтенду, который сохраняет структуру постоянных ссылок WordPress, больше ничего не требуется; фильтр vireo_headless_post_id сопоставляет всё, что отличается.','What this cannot see'=>'Что здесь не видно','Crawlers and AI bots are counted when they request a page from this WordPress site. Requests they make to the front end never reach it, so the crawler figures on the dashboard cover WordPress only; your front-end host\'s logs have the rest.'=>'Краулеры и ИИ-боты учитываются, когда запрашивают страницу с этого сайта WordPress. Их запросы к фронтенду сюда не попадают, поэтому данные о краулерах на панели охватывают только WordPress; остальное есть в логах хостинга вашего фронтенда.','Connect Search Console for the front-end address, since that is the site Google indexes. Core Web Vitals are not collected from the front end in this version.'=>'Подключите Search Console для адреса фронтенда: именно этот сайт индексирует Google. В этой версии Core Web Vitals с фронтенда не собираются.','Exclusions'=>'Исключения','Skip pageviews from known bots, your own IPs, or internal paths. Bot UAs are filtered automatically; these rules run on top.'=>'Пропускать просмотры от известных ботов, ваших собственных IP-адресов или внутренних путей. UA ботов фильтруются автоматически; эти правила действуют дополнительно.','Excluded IPs / CIDR'=>'Исключённые IP / CIDR','One entry per line. IPv4, IPv6, and CIDR ranges are supported.'=>'По одной записи в строке. Поддерживаются IPv4, IPv6 и диапазоны CIDR.','Excluded paths'=>'Исключённые пути','One path pattern per line. Use <code>*</code> for any chars except <code>/</code>, <code>**</code> for any chars.'=>'По одному шаблону пути в строке. Используйте <code>*</code> для любых символов, кроме <code>/</code>, и <code>**</code> для любых символов.','Blocked referrers'=>'Заблокированные реферреры','Sites whose visits are filtered like bots and hidden from reports. Known referrer spam is blocked already; these are the ones you added from a referrer row.'=>'Сайты, визиты с которых фильтруются как боты и скрываются из отчётов. Известный реферальный спам уже заблокирован; здесь те, которые вы добавили из строки реферрера.','Blocked hosts'=>'Заблокированные хосты','One host per line; subdomains are included. Remove a line to unblock it. Blocking stops counting from now on and hides earlier rows; nothing is deleted.'=>'Один хост на строку; поддомены включены. Чтобы разблокировать хост, удалите его строку. Блокировка прекращает учёт с этого момента и скрывает прежние записи; ничего не удаляется.','Geo-location'=>'Геолокация','Countries'=>'Страны','Resolving'=>'Определяются','Your host or CDN already tells us each visitor\'s country (it reported %s for this request), so countries resolve automatically. No database needed.'=>'Ваш хостинг или CDN уже сообщает страну каждого посетителя (для этого запроса указано %s), поэтому страны определяются автоматически. База данных не нужна.','Installed'=>'Установлена','Country lookups run against the local database on this server.'=>'Определение стран выполняется по локальной базе данных на этом сервере.','Geolocation by <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a>.'=>'Геолокация от <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a>.','Not resolving'=>'Не определяются','Every visitor is recorded as unknown until a country source is available. The one-click database below fixes it.'=>'Каждый посетитель записывается как неизвестный, пока не появится источник данных о странах. База данных ниже, устанавливаемая одним щелчком, это исправит.','Download country database'=>'Загрузить базу данных стран','Free, no account, installed for you. Data by <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a> (CC BY 4.0).'=>'Бесплатно, без учётной записи, устанавливается автоматически. Данные от <a href="https://db-ip.com" target="_blank" rel="noopener">DB-IP</a> (CC BY 4.0).','Prefer MaxMind GeoLite2? (manual)'=>'Предпочитаете MaxMind GeoLite2? (вручную)','Create a free account at <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noopener">maxmind.com</a> and generate a license key.'=>'Создайте бесплатную учётную запись на <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noopener">maxmind.com</a> и сгенерируйте лицензионный ключ.','Download <code>GeoLite2-Country.mmdb</code> (the Country edition is enough).'=>'Загрузите <code>GeoLite2-Country.mmdb</code> (достаточно версии Country).','Upload it to <code>%s/</code> on this server.'=>'Загрузите его в <code>%s/</code> на этом сервере.','MaxMind requires an account and prohibits automatic downloads, which is why it is manual.'=>'MaxMind требует учётную запись и запрещает автоматическую загрузку, поэтому это делается вручную.','Excluded countries'=>'Исключённые страны','One two-letter country code per line. Traffic from these countries is discarded instead of counted, the same as an excluded IP. Bots that announce themselves are already filtered; this is for the traffic that does not.'=>'По одному двухбуквенному коду страны на строку. Трафик из этих стран отбрасывается, а не учитывается — так же, как и с исключённым IP. Боты, которые сами себя объявляют, уже отфильтрованы; это поле — для трафика, который этого не делает.','Needs the country to be known, so it requires either a host that resolves it or the database above.'=>'Страна должна быть определена, поэтому нужен либо хостинг, который её определяет, либо база данных выше.','Excluding a country stops it being counted from now on. It does not remove what was counted before, so a report covering earlier dates still shows it.'=>'Исключённая страна перестаёт учитываться с этого момента. Уже учтённые данные не удаляются, поэтому в отчёте за более ранние даты она по-прежнему отображается.','Remove stored data for %s'=>'Удалить сохранённые данные для %s','Clears them from the countries report. Pageview and visitor totals keep those visits, because nothing else records which country a visit came from.'=>'Удаляет их из отчёта по странам. В итоговых просмотрах и посетителях эти визиты останутся, потому что больше нигде не записывается, из какой страны пришёл визит.','Auto-events'=>'Авто-события','Record common clicks and form sends as events, with no code to add. Each one shows up on the Campaigns tab.'=>'Записывать частые клики и отправки форм как события, без кода. Они появятся на вкладке «Кампании».','File downloads'=>'Загрузки файлов','Record clicks on links to files (PDF, ZIP, DOC, MP3, MP4, etc.).'=>'Регистрировать клики по ссылкам на файлы (PDF, ZIP, DOC, MP3, MP4 и т. д.).','Fires a "download" event with the filename as the value.'=>'Отправляет событие «download» со значением, равным имени файла.','Form submissions'=>'Отправка форм','Record every form submit.'=>'Регистрировать каждую отправку формы.','Fires a "form_submit" event with the form id, name, or action URL.'=>'Отправляет событие «form_submit» с id, именем или URL действия формы.','Email links'=>'Ссылки на email','Record clicks on mailto: links.'=>'Регистрировать клики по ссылкам mailto:.','Only the part after the @ is kept, so no email address is stored.'=>'Сохраняется только часть после @, поэтому адреса электронной почты не хранятся.','Phone links'=>'Телефонные ссылки','Record clicks on tel: links.'=>'Регистрировать клики по ссылкам tel:.','Outbound links'=>'Внешние ссылки','Record clicks on links to external domains.'=>'Регистрировать клики по ссылкам на внешние домены.','Pro records outbound clicks with more detail, so this option is off to avoid counting each click twice.'=>'Pro записывает исходящие клики подробнее, поэтому эта опция выключена, чтобы не считать каждый клик дважды.','Fires an "outbound" event with the external host as the value.'=>'Отправляет событие «outbound» со значением, равным внешнему хосту.','The last day, week or month in one email: top pages, referrers and countries. It\'s built on your server and sent with your site\'s own mail.'=>'Итоги за последний день, неделю или месяц в одном письме: топ страниц, реферреры и страны. Письмо формируется на вашем сервере и отправляется через почту вашего сайта.','Enable'=>'Включить','Send the digest'=>'Отправлять сводку','Frequency'=>'Периодичность','Every morning, covering the day before.'=>'Каждое утро, за предыдущий день.','Once a week, covering the last seven full days.'=>'Раз в неделю, за последние семь полных дней.','On the first of each month, covering the month before.'=>'Первого числа каждого месяца, за предыдущий месяц.','Recipients'=>'Получатели','One email per line. Leave blank to fall back to the site admin (%s).'=>'По одному адресу в строке. Оставьте пустым, чтобы использовать администратора сайта (%s).','When'=>'Когда','Hour'=>'Час','Site timezone (%s).'=>'Часовой пояс сайта (%s).','Save settings'=>'Сохранить настройки','Connected sites'=>'Подключённые сайты','Count visits to other sites you run, whether or not they use WordPress: a static site, a docs site, a landing page. Each connected site keeps its own numbers, and the dashboard switches between them. Unlike the headless front end above, its pages are not matched to posts here.'=>'Учитывайте посещения других ваших сайтов, независимо от того, работают ли они на WordPress: статический сайт, сайт с документацией, посадочная страница. У каждого подключённого сайта своя статистика, а панель переключается между ними. В отличие от headless-фронтенда выше, страницы таких сайтов здесь не сопоставляются с записями.','Paste this before </body> on every page of the site. The second line collects Core Web Vitals and can be left out. For a site that changes pages without reloading, add data-spa="history" to the first tag.'=>'Вставьте это перед </body> на каждой странице сайта. Вторая строка собирает метрики Core Web Vitals, её можно не добавлять. Для сайта, который меняет страницы без перезагрузки, добавьте data-spa="history" в первый тег.','Pageviews are accepted only when the browser sends them from %s, so the tag records nothing if it is pasted anywhere else.'=>'Просмотры страниц принимаются, только если браузер отправляет их с адреса %s, поэтому тег ничего не запишет, если его вставить где-то ещё.','Remove this site…'=>'Удалить этот сайт…','This deletes every number recorded for %s. There is no undo. Type the site\'s name to confirm.'=>'Это удалит все данные, записанные для %s. Отменить действие нельзя. Для подтверждения введите название сайта.','Site name'=>'Название сайта','Remove site and its data'=>'Удалить сайт и его данные','Keep it'=>'Оставить','Docs site'=>'Сайт с документацией','Site address'=>'Адрес сайта','The address readers see in their browser, including https://. Visits sent from any other address are refused.'=>'Адрес, который читатели видят в браузере, включая https://. Посещения, отправленные с любого другого адреса, отклоняются.','Connect site'=>'Подключить сайт','This install allows %d connected site.'=>'Эта установка допускает %d подключённый сайт.' . "\0" . 'Эта установка допускает %d подключённых сайта.' . "\0" . 'Эта установка допускает %d подключённых сайтов.','Bot filter test'=>'Проверка фильтра ботов','Paste a User-Agent to see whether Vireo Analytics would filter it as a bot. Useful when debugging why a visitor (or monitoring tool) isn\'t showing up in stats.'=>'Вставьте User-Agent, чтобы увидеть, отфильтрует ли его Vireo Analytics как бота. Полезно при выяснении, почему посетитель (или инструмент мониторинга) не отображается в статистике.','User-Agent'=>'User-Agent','Test User-Agent'=>'Проверить User-Agent','Test email'=>'Тестовое письмо','Sends the digest for the last finished period to %s right now (bypasses the schedule).'=>'Прямо сейчас отправляет сводку за последний завершённый период на %s (в обход расписания).','Send test email'=>'Отправить тестовое письмо','Search Console'=>'Search Console','Search Console connected. The first sync runs shortly.'=>'Search Console подключён. Первая синхронизация начнётся в ближайшее время.','The last week is in. Older history is loading in the background a couple of weeks at a time, and should be complete in a few minutes.'=>'Последняя неделя загружена. Более ранняя история загружается в фоновом режиме по паре недель за раз и должна завершиться через несколько минут.','Search Console data refreshed.'=>'Данные Search Console обновлены.','Search Console disconnected.'=>'Search Console отключён.','Brings in the searches people ran before they arrived. Google strips the query from the referrer, so this is the only place it exists. Uses the same kind of service account key as the Analytics importer, with read-only access.'=>'Добавляет поисковые запросы, по которым люди попали на сайт. Google удаляет запрос из реферера, так что это единственное место, где он вообще есть. Использует такой же ключ сервисного аккаунта, как импорт из Analytics, только с доступом на чтение.','Under APIs and services, enable the Google Search Console API.'=>'В разделе «API и сервисы» включите Google Search Console API.','Under IAM and admin, then Service accounts, create a service account. Its address ends in .iam.gserviceaccount.com. You need that address for the next part.'=>'В разделе «IAM и администрирование» → «Сервисные аккаунты» создайте сервисный аккаунт. Его адрес заканчивается на .iam.gserviceaccount.com. Он понадобится для следующего шага.','In Search Console'=>'В Search Console','Open Settings, then Users and permissions, and add the service account address with Restricted access.'=>'Откройте «Настройки» → «Пользователи и разрешения» и добавьте адрес сервисного аккаунта с ограниченным доступом (Restricted).','Copy the property exactly as Search Console lists it. A domain property looks like sc-domain:example.com. A URL-prefix property is the full address including https:// and any trailing slash. The two are different properties and the wrong one returns nothing.'=>'Скопируйте ресурс точно так, как он указан в Search Console. Ресурс типа «домен» выглядит как sc-domain:example.com. Ресурс типа «префикс URL» — это полный адрес, включая https:// и завершающий слэш, если он есть. Это разные типы ресурсов, и неверный вариант не вернёт данных.','Then open the downloaded file in a text editor and paste all of it, braces included, into the box below.'=>'Затем откройте скачанный файл в текстовом редакторе и вставьте его целиком, включая фигурные скобки, в поле ниже.','The last sync failed: %s'=>'Последняя синхронизация не удалась: %s','Last refreshed %1$s ago, covering %2$s to %3$s.'=>'Последнее обновление: %1$s назад, за период с %2$s по %3$s.','Add %s as a user on the property in Search Console, with Restricted access.'=>'Добавьте %s как пользователя ресурса в Search Console с ограниченным доступом (Restricted).','Property'=>'Ресурс','Copy it exactly as Search Console shows it. A domain property looks like sc-domain:example.com.'=>'Скопируйте его точно так, как он указан в Search Console. Ресурс типа «домен» выглядит как sc-domain:example.com.','Save Search Console settings'=>'Сохранить настройки Search Console','Fetch the last 90 days'=>'Загрузить данные за последние 90 дней','Disconnect'=>'Отключить','PageSpeed Insights'=>'PageSpeed Insights','API key saved. Tests now run from the dashboard and show their results there.'=>'Ключ API сохранён. Теперь тесты запускаются на панели, и результаты отображаются там же.','API key removed.'=>'Ключ API удалён.','The Page speed tab and each post\'s stats have a button for Google\'s lab test. Without a key it opens the test on the PageSpeed Insights website. With your own free Google API key, the test runs from here and the results show on the dashboard, next to the speed your real visitors got. A test only runs when someone presses the button.'=>'На вкладке «Скорость страниц» и в статистике каждой записи есть кнопка лабораторного теста Google. Без ключа тест открывается на сайте PageSpeed Insights. Если добавить собственный бесплатный ключ Google API, тест запускается прямо здесь, а результаты отображаются на панели рядом со скоростью, которую получили ваши реальные посетители. Тест запускается только после нажатия кнопки.','%s, or pick one you already have. Any name works.'=>'%s или выберите уже существующий. Подойдёт любое название.','Create a Google Cloud project'=>'Создайте проект в Google Cloud','%s for that project.'=>'%s для этого проекта.','Enable the PageSpeed Insights API'=>'Включите PageSpeed Insights API','On the %s page, choose Create credentials, then API key.'=>'На странице «%s» выберите «Создать учётные данные», затем «Ключ API».','Credentials'=>'Учётные данные','Open the new key. Under API restrictions, choose Restrict key, select PageSpeed Insights API, and save.'=>'Откройте новый ключ. В разделе «Ограничения API» выберите «Ограничить ключ», отметьте PageSpeed Insights API и сохраните.','Copy the key and paste it below.'=>'Скопируйте ключ и вставьте его ниже.','Google API key (optional)'=>'Ключ Google API (необязательно)','A key is saved.'=>'Ключ сохранён.','Save API key'=>'Сохранить ключ API','Remove API key'=>'Удалить ключ API','REST API'=>'REST API','Endpoints and an example request'=>'Эндпоинты и пример запроса','Read-only endpoints under /wp-json/vireo-analytics/v1. Authenticate with WordPress Application Passwords or a logged-in session nonce. Requires the view_vireo_analytics capability.'=>'Конечные точки только для чтения по адресу /wp-json/vireo-analytics/v1. Аутентификация через пароли приложений WordPress или nonce авторизованной сессии. Требуется право view_vireo_analytics.','Base URL'=>'Базовый URL','Endpoints'=>'Конечные точки','Example'=>'Пример','Connect an AI assistant'=>'Подключить ИИ-ассистента','Ask Claude, Cursor or any other MCP client about this site\'s traffic in plain language: what changed this week, which pages are growing, what people searched for. The assistant signs in as you with an application password and sees exactly what you can see in the dashboard, read-only.'=>'Спрашивайте Claude, Cursor или любой другой MCP-клиент о трафике этого сайта простым языком: что изменилось на этой неделе, какие страницы растут, что искали люди. Ассистент входит от вашего имени с помощью пароля приложения и видит ровно то же, что и вы в панели, только для чтения.','The bundled MCP adapter is missing from this install, so the endpoint is off. Reinstall the plugin from its release package.'=>'В этой установке отсутствует встроенный адаптер MCP, поэтому конечная точка отключена. Переустановите плагин из его релизного пакета.','MCP endpoint'=>'Конечная точка MCP','Copy'=>'Копировать','Application password'=>'Пароль приложения','Create one on your profile'=>'Создайте его в своём профиле','and name it after the assistant. Paste it where the snippets below say APP_PASSWORD; the spaces WordPress shows in it can stay. You can revoke it from the same place at any time.'=>'и назовите по имени ассистента. Вставьте его туда, где в сниппетах ниже указано APP_PASSWORD; пробелы, которые показывает WordPress, можно оставить. Отозвать пароль можно в любой момент там же.','Only users who can open the Vireo dashboard can connect. A password for anyone else is refused.'=>'Подключиться могут только пользователи, у которых есть доступ к панели Vireo. Пароль любого другого пользователя будет отклонён.','Claude Code'=>'Claude Code','Run it in a terminal, then ask Claude Code about your traffic.'=>'Запустите команду в терминале, затем спросите Claude Code о вашем трафике.','Claude Desktop, Cursor and others'=>'Claude Desktop, Cursor и другие','Add it to the client\'s MCP settings file (claude_desktop_config.json, Cursor\'s mcp.json). Needs Node.js on that computer; the proxy runs locally and talks to this site over HTTPS.'=>'Добавьте это в файл настроек MCP вашего клиента (claude_desktop_config.json, mcp.json в Cursor). Нужен Node.js на этом компьютере; прокси работает локально и обращается к сайту по HTTPS.','Import data'=>'Импорт данных','Bring your history into Vireo Analytics. Your source data is never modified. An import adds to what is already stored and can\'t be undone, so import any range only once.'=>'Перенесите свою историю в Vireo Analytics. Исходные данные никогда не изменяются. Импорт добавляется к уже сохранённым данным и не может быть отменён, поэтому импортируйте каждый период только один раз.','Found on this site'=>'Найдено на этом сайте','A Google Analytics plugin is active on this site.'=>'На этом сайте активен плагин Google Analytics.','Active, with data stored on this site.'=>'Активен, данные хранятся на этом сайте.','Active on this site.'=>'Активен на этом сайте.','No longer active, but its data is still stored on this site.'=>'Больше не активен, но его данные всё ещё хранятся на этом сайте.','None of the analytics plugins Vireo Analytics imports from is active on this site, and none has left data here. If you have used one of these, or still have its data elsewhere:'=>'Ни один из плагинов аналитики, из которых Vireo Analytics может импортировать данные, не активен на этом сайте и не оставил здесь данных. Если вы пользовались одним из них или у вас остались его данные в другом месте:','Vireo Analytics can also import from:'=>'Vireo Analytics также может импортировать данные из:','These import from the data a plugin leaves on this site. None was found yet:'=>'Эти источники импортируют данные, которые плагин оставляет на сайте. Пока ничего не найдено:','Backup and restore'=>'Резервное копирование и восстановление','Download everything Vireo Analytics has recorded for this site as one file, and load it on another install, or back onto this one. Loading the same file twice gives the same numbers, so a restore can be repeated safely. Settings, connected sites and the live visitor buffer are not included.'=>'Скачайте всё, что Vireo Analytics записал для этого сайта, одним файлом и загрузите его на другой установке или обратно на этой же. Повторная загрузка того же файла даёт те же цифры, поэтому восстановление можно безопасно повторять. Настройки, подключённые сайты и буфер посетителей в реальном времени не включаются.','Download backup'=>'Скачать резервную копию','Restore from a backup'=>'Восстановить из резервной копии','Export CSV'=>'Экспорт CSV','Download your analytics for the dates below as a CSV file. It\'s built on your server and goes straight to your browser.'=>'Скачайте статистику за выбранные ниже даты в виде CSV-файла. Он собирается на вашем сервере и сразу отправляется в браузер.','Site totals'=>'Итоги по сайту','Pages'=>'Страницы','Referrers'=>'Источники переходов','Devices'=>'Устройства','Broken links'=>'Битые ссылки','Events'=>'События','Type'=>'Тип','Download CSV'=>'Скачать CSV','Questions or a bug? %s.'=>'Есть вопросы или нашли ошибку? %s.','Ask in the support forum'=>'Спросите на форуме поддержки','No 404 errors in this period'=>'За этот период нет ошибок 404','Broken links and missing pages hit by visitors will appear here.'=>'Здесь появятся неработающие ссылки и отсутствующие страницы, на которые попадали посетители.','Path'=>'Путь','Top referrer'=>'Основной источник перехода','Hits'=>'Обращения','No broken links'=>'Битых ссылок нет','Nothing on your site links to a page that is missing.'=>'На вашем сайте нет ссылок на отсутствующие страницы.','Pages on your site linking somewhere missing. Fix the linking page.'=>'Страницы вашего сайта, ссылающиеся на отсутствующие адреса. Исправьте страницу со ссылкой.','Missing page'=>'Отсутствующая страница','Linked from'=>'Ссылка с','+%s more page'=>'+ещё %s страница' . "\0" . '+ещё %s страницы' . "\0" . '+ещё %s страниц','Requests from elsewhere'=>'Запросы из других источников','Nothing on your site links to these. Mostly automated scanners looking for software you do not run; occasionally a stale link elsewhere worth a redirect.'=>'На вашем сайте нет ссылок на эти адреса. В основном это автоматические сканеры, ищущие ПО, которого у вас нет; изредка — устаревшая ссылка на другом ресурсе, для которой стоит сделать редирект.','Referrer'=>'Реферер','no referrer'=>'без реферера','requests from their crawlers'=>'запросов их краулеров','readers they sent back'=>'читателей они прислали','crawler requests per reader sent'=>'запросов краулеров на одного приведённого читателя','Since %s, when Vireo started counting crawlers. Earlier days in this range have readers but no crawler figures, so this card leaves them out.'=>'С %s, когда Vireo начал учитывать краулеры. За более ранние дни этого диапазона есть данные о читателях, но нет данных о краулерах, поэтому эта карточка их не учитывает.','Assistant'=>'Ассистент','Readers sent'=>'Прислано читателей','No assistant has sent a reader to this site in this period, though their crawlers have been reading it.'=>'За этот период ни один ассистент не прислал читателя на этот сайт, хотя их краулеры его посещали.','Crawler figures count requests the bot filter held back. Readers sent counts people who arrived by following a link inside an assistant, which is the closest thing there is to being recommended by one.'=>'Цифры краулеров — это запросы, которые задержал фильтр ботов. «Прислано читателей» — это люди, пришедшие по ссылке внутри ассистента, что ближе всего к тому, чтобы быть рекомендованным им.','Notes'=>'Заметки','Remove the note for %s'=>'Удалить заметку за %s','Nothing noted in this range yet.'=>'За этот период заметок пока нет.','Date'=>'Дата','What happened'=>'Что произошло','Newsletter went out'=>'Рассылка отправлена','Add note'=>'Добавить заметку','%s request kept out of the numbers above.'=>'%s запрос не учтён в приведённых выше данных.' . "\0" . '%s запроса не учтены в приведённых выше данных.' . "\0" . '%s запросов не учтено в приведённых выше данных.','That is under 0.1%% of the requests Vireo saw.'=>'Это менее 0,1%% запросов, которые зафиксировал Vireo.','That is %s%% of the requests Vireo saw.'=>'Это %s%% всех запросов, которые увидел Vireo.','What was filtered and why'=>'Что отфильтровано и почему','None of these reached your visitor or pageview totals. It is also why those totals sit below what a server-log tool reports: log readers count every crawler, monitor and scraper as a visit. Crawlers are counted when they ask WordPress for a page, so on a site with full-page caching the real numbers are higher than these: a cached page is answered before WordPress runs, and nothing inside WordPress can see that request.'=>'Ни один из них не попал в итоги посетителей или просмотров. Поэтому эти итоги ниже, чем показывают инструменты анализа серверных логов: они считают визитом каждого краулера, монитора и сборщика данных. Краулеры учитываются, когда обращаются к WordPress за страницей, поэтому на сайте с полным кэшированием страниц реальные цифры выше этих: кэшированная страница отдаётся до запуска WordPress, и внутри WordPress увидеть такой запрос невозможно.','Got it'=>'Понятно','Both'=>'Оба','Prior period'=>'Предыдущий период','Hourly traffic'=>'Почасовой трафик','Daily traffic'=>'Ежедневный трафик','Chart granularity'=>'Детализация графика','Chart metric'=>'Метрика графика','%s, whole days'=>'%s, полные дни','No traffic yet'=>'Пока нет трафика','Pageviews for the selected range will plot here as they are recorded.'=>'Просмотры за выбранный диапазон будут отображаться здесь по мере их регистрации.','View'=>'Вид','Map'=>'Карта','Table'=>'Таблица','Countries are not being resolved'=>'Страны не определяются','The geo-location database is not installed, so every visitor is recorded as unknown. Your traffic is still being counted.'=>'База данных геолокации не установлена, поэтому каждый посетитель записывается как неизвестный. Ваш трафик по-прежнему учитывается.','Set it up'=>'Настроить','No country data yet'=>'Пока нет данных о странах','Geo-located pageviews will appear here once visitors arrive.'=>'Просмотры с определённой геолокацией появятся здесь, как только придут посетители.','World map of visitor distribution'=>'Карта мира с распределением посетителей','Country known for %s%% of visitors.'=>'Страна известна для %s%% посетителей.','Filter by %s'=>'Фильтр по %s','Device types'=>'Типы устройств','Browsers'=>'Браузеры','Operating systems'=>'Операционные системы','Technology breakdown'=>'Разбивка по технологиям','No data for this period.'=>'Нет данных за этот период.','visitor'=>'посетитель' . "\0" . 'посетителя' . "\0" . 'посетителей','Gained'=>'Прирост','Nothing grew.'=>'Ничего не выросло.','Lost'=>'Потери','Nothing fell.'=>'Ничего не упало.','Show all pages'=>'Показать все страницы','Sources'=>'Источники','Show all sources'=>'Показать все источники','Fix this'=>'Исправить','&larr; Overview'=>'&larr; Обзор','Total count'=>'Всего срабатываний','times recorded in this range'=>'раз записано за этот период','Unique visitors'=>'Уникальные посетители','daily visitors, added up'=>'ежедневные посетители, сложенные','Distinct values'=>'Уникальные значения','in this range, top %d listed below'=>'за этот период, топ-%d ниже','in this range'=>'за этот период','Daily counts'=>'Ежедневные значения','Count'=>'Количество','Unique'=>'Уникальные','Nothing recorded in this range'=>'За этот период ничего не записано','Event counts for the selected range will plot here as they are recorded.'=>'Число событий за выбранный диапазон будет отображаться здесь по мере их регистрации.','Top values'=>'Топ значений','No values recorded'=>'Значения не зафиксированы','Send a value with this event to see a breakdown here.'=>'Передайте значение вместе с этим событием, чтобы увидеть здесь разбивку.','(no value)'=>'(нет значения)','&larr; back to all events'=>'&larr; ко всем событиям','Top events'=>'Топ событий','No events recorded'=>'События не зафиксированы','Fire events from your site with <code>vireo(\'event\', \'name\')</code> and they\'ll appear here.'=>'Отправляйте события со своего сайта с помощью <code>vireo(\'event\', \'name\')</code>, и они появятся здесь.','not available with these filters'=>'недоступно при этих фильтрах','in the selected range'=>'за выбранный диапазон','daily uniques, summed'=>'сумма ежедневных уникальных','unique today'=>'уникальных сегодня','Someone who visits on more than one day is counted once per day. Visitors are identified by a hash whose salt is regenerated every night, so the same person cannot be recognised across days. That is deliberate: it is what lets Vireo track visitors without cookies and without consent.'=>'Тот, кто заходит в течение нескольких дней, учитывается один раз в день. Посетители идентифицируются по хешу, соль которого обновляется каждую ночь, поэтому один и тот же человек не может быть распознан в разные дни. Это сделано намеренно: именно так Vireo отслеживает посетителей без cookie и без согласия.','Unique visitors today.'=>'Уникальных посетителей сегодня.','Average daily traffic'=>'Средний трафик в день','over %d day'=>'за %d день' . "\0" . 'за %d дня' . "\0" . 'за %d дней','not split by filters'=>'не разделено по фильтрам','Time on page is measured for the whole site, so it is not shown while a filter is on.'=>'Время на странице измеряется для всего сайта, поэтому при включённом фильтре оно не показывается.','average active time'=>'среднее активное время','The average of the %s view that reported a time. Only time with the tab in front of the reader counts, up to 30 minutes a view, and views closed before they reported are left out.'=>'Среднее по %s просмотру, который передал время. Учитывается только время, когда вкладка открыта перед читателем, не более 30 минут на просмотр; просмотры, закрытые до передачи данных, не учитываются.' . "\0" . 'Среднее по %s просмотрам, которые передали время. Учитывается только время, когда вкладка открыта перед читателем, не более 30 минут на просмотр; просмотры, закрытые до передачи данных, не учитываются.' . "\0" . 'Среднее по %s просмотрам, которые передали время. Учитывается только время, когда вкладка открыта перед читателем, не более 30 минут на просмотр; просмотры, закрытые до передачи данных, не учитываются.','Time on page'=>'Время на странице','Bounce rate is measured for the whole site, so it is not shown while a filter is on.'=>'Показатель отказов измеряется для всего сайта, поэтому при включённом фильтре он не показывается.','visitors who viewed one page'=>'посетители, просмотревшие одну страницу','The share of visitors who viewed exactly one page in a day. A visitor is counted the same way as on the Visitors card, once per day, so someone who comes back on another day counts again.'=>'Доля посетителей, просмотревших ровно одну страницу за день. Посетитель учитывается так же, как в карточке «Посетители»: один раз в день, поэтому тот, кто возвращается в другой день, учитывается снова.','Bounce rate'=>'Показатель отказов','The %1$s figures come from history imported from %2$s.'=>'Данные %1$s взяты из истории, импортированной из %2$s.','This week'=>'Эта неделя','Compared with the same period last year, up to the same time of day.'=>'По сравнению с тем же периодом прошлого года, до того же времени суток.','Compared with the same period last year.'=>'По сравнению с тем же периодом прошлого года.','Compared with the period before, up to the same time of day.'=>'В сравнении с предыдущим периодом до того же часа.','Compared with the period before.'=>'В сравнении с предыдущим периодом.','Performance score'=>'Оценка производительности','What Google suggests fixing first'=>'Что Google советует исправить в первую очередь','Nothing with a measurable saving. This page passed the checks that matter most.'=>'Нет проблем с измеримым выигрышем. Эта страница прошла самые важные проверки.','Tested as a desktop visitor %s ago.'=>'Проверено как посетитель с компьютера %s назад.','Tested as a phone visitor %s ago.'=>'Проверено как посетитель с телефона %s назад.','Run again'=>'Запустить снова','Full report on PageSpeed Insights'=>'Полный отчёт в PageSpeed Insights','(opens in a new tab)'=>'(откроется в новой вкладке)','Lab: one test by Google'=>'Лабораторные данные: один тест от Google','Device to test as'=>'Устройство для проверки','Test this page on PageSpeed Insights'=>'Проверить эту страницу в PageSpeed Insights','Add a free Google API key in Settings to see the results right here instead.'=>'Добавьте бесплатный ключ Google API в разделе «Настройки», чтобы видеть результаты прямо здесь.','An administrator can add a free Google API key in Settings to show the results right here instead.'=>'Администратор может добавить бесплатный ключ Google API в настройках, чтобы результаты отображались прямо здесь.','Google loads this page once on its own servers, as a desktop visitor, and lists what would make it faster. It takes up to a minute.'=>'Google один раз загружает эту страницу на своих серверах как посетитель с компьютера и перечисляет, что ускорит её загрузку. Это занимает до минуты.','Google loads this page once on its own servers, as a phone visitor on a slow connection, and lists what would make it faster. It takes up to a minute.'=>'Google один раз загружает эту страницу на своих серверах как посетитель с телефона при медленном соединении и перечисляет, что ускорит её загрузку. Это занимает до минуты.','Run test'=>'Запустить тест','Lifetime pageviews'=>'Просмотры за всё время','since %s'=>'с %s','Lifetime visitors'=>'Посетители за всё время','Best day'=>'Лучший день','no traffic yet'=>'пока нет трафика','Daily traffic · %1$s &ndash; %2$s'=>'Ежедневный трафик · %1$s &ndash; %2$s','No traffic in this range'=>'Нет трафика за этот период','Pageviews for this post will plot here as they are recorded.'=>'Просмотры этой записи будут отображаться здесь по мере их регистрации.','pageviews in range'=>'просмотров за период','visitors in range'=>'посетителей за период','comment in range'=>'комментарий за период' . "\0" . 'комментария за период' . "\0" . 'комментариев за период','comments per 1,000 views'=>'комментариев на 1000 просмотров','Page speed for this post'=>'Скорость загрузки этой записи','Speed from your real visitors is measured for the whole site, not per post.'=>'Скорость для реальных посетителей измеряется для всего сайта, а не для отдельных записей.','See it on the Overview'=>'Посмотреть в «Обзоре»','This post, tested by Google'=>'Эта запись, проверенная Google','Test this post with Google'=>'Проверить эту запись с помощью Google','Top referrers for this post'=>'Источники переходов для этой записи','No referrers in this range'=>'Нет источников переходов за этот период','This post had no inbound referrers during the selected period.'=>'У этой записи не было входящих переходов за выбранный период.','Per-post referrer data is being collected'=>'Данные об источниках переходов по записям собираются','Referrers per individual post started tracking with a recent update. Data will appear here as new visitors arrive.'=>'Отслеживание источников переходов по отдельным записям началось с недавнего обновления. Данные появятся здесь по мере прихода новых посетителей.','Referrer data for this post starts from %s.'=>'Данные об источниках переходов для этой записи доступны с %s.','Searches that found this post'=>'Поисковые запросы, которые привели к этой записи','See what people searched for'=>'Посмотрите, что искали люди','Only Search Console knows which searches showed this post. Connect it to list them here.'=>'Только Search Console знает, в каких поисках появлялась эта запись. Подключите её, чтобы увидеть их здесь.','Connect Search Console'=>'Подключить Search Console','No searches for this post in this range'=>'Нет поисковых запросов для этой записи за этот период','Google reports search data about three days late, so the most recent days are always empty.'=>'Google публикует данные поиска с задержкой примерно в три дня, поэтому последние дни всегда пусты.','Clicks · position'=>'Клики · позиция','Shown %s time'=>'Показано %s раз' . "\0" . 'Показано %s раза' . "\0" . 'Показано %s раз','%1$s. Printed %2$s from Vireo Analytics.'=>'%1$s. Напечатано %2$s из Vireo Analytics.','Traffic from this referrer · %1$s to %2$s'=>'Трафик от этого источника · с %1$s по %2$s','Pageviews in range'=>'Просмотры за период','Visitors in range'=>'Посетители за период','No traffic from this referrer in this range'=>'Нет трафика от этого источника за этот период','Pageviews sent by this source will plot here as they are recorded.'=>'Просмотры, приведённые этим источником, будут отображаться здесь по мере их регистрации.','Posts it sent people to'=>'Записи, куда он направил посетителей','Pageviews on each post from this referrer. Home and archive pages aren\'t broken down this way.'=>'Просмотры каждой записи с этого источника. Главная страница и архивы так не разбиваются.','Vireo has been counting here for %s day. If it has been useful, a review on WordPress.org helps other site owners find it.'=>'Vireo ведёт подсчёт на этом сайте уже %s день. Если плагин оказался полезным, отзыв на WordPress.org поможет другим владельцам сайтов его найти.' . "\0" . 'Vireo ведёт подсчёт на этом сайте уже %s дня. Если плагин оказался полезным, отзыв на WordPress.org поможет другим владельцам сайтов его найти.' . "\0" . 'Vireo ведёт подсчёт на этом сайте уже %s дней. Если плагин оказался полезным, отзыв на WordPress.org поможет другим владельцам сайтов его найти.','Leave a review'=>'Оставить отзыв','Not now'=>'Не сейчас','Don\'t ask again'=>'Больше не спрашивать','Searches that found you'=>'Поисковые запросы, по которым вас нашли','clicks from search'=>'переходов из поиска','times you appeared'=>'показов','click-through rate'=>'CTR','average position'=>'средняя позиция','Clicks'=>'Клики','Impressions'=>'Показы','Position'=>'Позиция','The page Google most often showed for this search'=>'Страница, которую Google чаще всего показывал по этому запросу','From Search Console, which reports a few days behind and leaves out rare searches.'=>'Данные из Search Console: отчёт запаздывает на несколько дней и не включает редкие запросы.','posts opened'=>'открыто записей','links followed from a post'=>'переходов по ссылкам из записи','Follow clicks'=>'Клики по кнопке «Подписаться»','Load more clicks'=>'Клики по кнопке «Загрузить ещё»','Instagram feeds'=>'Ленты Instagram','Page with a feed'=>'Страница с лентой','Posts opened'=>'Открыто записей','No pages tracked yet'=>'Пока не отслежено ни одной страницы','Top posts and pages will appear here after the first few visits.'=>'Топ записей и страниц появится здесь после первых посещений.','Average active time on this page: %s'=>'Среднее активное время на этой странице: %s','(unpublished)'=>'(не опубликовано)','Visitors who arrived with no referrer: typed the URL, used a bookmark, or came from an app or email client.'=>'Посетители, пришедшие без источника перехода: ввели URL вручную, использовали закладку или перешли из приложения либо почтового клиента.','No search traffic in this range.'=>'Нет поискового трафика за этот период.','No AI assistant traffic in this range.'=>'За этот период нет трафика от ИИ-ассистентов.','No social traffic in this range.'=>'Нет трафика из соцсетей за этот период.','No referral traffic in this range.'=>'Нет реферального трафика за этот период.','No referrers yet'=>'Пока нет источников переходов','When someone clicks through from another site, they\'ll show up here.'=>'Когда кто-то перейдёт с другого сайта, он появится здесь.','None of these made the top ten. Filter by this source to list them.'=>'Ни один из них не вошёл в топ-10. Отфильтруйте по этому источнику, чтобы увидеть их список.','Every visit from this site viewed one page and none landed on a post, over a burst of days. That is what a compromised site or a spoofed referrer looks like, not readers. Nothing is removed until you block it.'=>'Все визиты с этого сайта ограничились одной просмотренной страницей, и ни один не попал на запись, причём так продолжалось несколько дней подряд. Так выглядит взломанный сайт или подмена реферера, а не живые читатели. Пока вы не заблокируете источник, ничего не удаляется.','suspected junk'=>'подозрение на мусорный трафик','Block this referrer'=>'Заблокировать этот реферер','Page speed from real visits'=>'Скорость страниц по реальным визитам','No speed measurements from real visits in this range yet. They appear as people load your pages.'=>'За этот период измерений скорости по реальным посещениям пока нет. Они появятся, когда люди начнут загружать ваши страницы.','75th percentile: three in four visits were at least this fast.'=>'75-й процентиль: три из четырёх визитов были не медленнее.','Google grades pages on this line rather than the average, so the slowest quarter of visits counts against you.'=>'Google оценивает страницы по этому значению, а не по среднему, поэтому самая медленная четверть визитов идёт вам в минус.','Only %s real visit measured so far, so expect these to move.'=>'Пока измерено всего %s реальное посещение, так что значения ещё могут измениться.' . "\0" . 'Пока измерено всего %s реальных посещения, так что значения ещё могут измениться.' . "\0" . 'Пока измерено всего %s реальных посещений, так что значения ещё могут измениться.','Measured from %s real visit, not a lab test.'=>'Рассчитано по %s реальному посещению, а не по лабораторному тесту.' . "\0" . 'Рассчитано по %s реальным посещениям, а не по лабораторному тесту.' . "\0" . 'Рассчитано по %s реальным посещениям, а не по лабораторному тесту.','Your homepage, tested by Google'=>'Ваша главная страница, проверенная Google','Test your homepage with Google'=>'Проверить главную страницу с помощью Google','Aggregated content'=>'Агрегированный контент','views of imported posts'=>'просмотров импортированных записей','clicks through to the original articles'=>'переходов к оригинальным статьям','of all pageviews were imported posts'=>'всех просмотров приходится на импортированные записи','Feed source'=>'Источник ленты','Views here'=>'Просмотры здесь','Clicks out'=>'Переходы на источник','Clicks out count readers who followed an item to the site it came from, recorded from the day this version of Vireo was installed.'=>'Переходы на источник показывают, сколько читателей перешли от записи на сайт, откуда она взята. Данные собираются с того дня, как была установлена эта версия Vireo.','Views here count visits to items imported as posts.'=>'В «Просмотрах здесь» учитываются посещения записей, импортированных как посты.','Your %d in review is ready.'=>'Итоги %d года готовы.','See it'=>'Посмотреть','%d so far'=>'%d на данный момент','%d in review'=>'Итоги %d года','vs the same days of %d'=>'по сравнению с теми же днями %d года','vs %d'=>'по сравнению с %d','No full record of %d to compare with'=>'Нет полных данных за %d для сравнения','Year'=>'Год','Copy summary'=>'Скопировать сводку','Print'=>'Печать','Nothing recorded for %d yet'=>'За %d пока ничего не записано','This review fills in on its own as visits are recorded; the first ones show up within a minute. If another analytics tool counted this year, its history can be imported and shows here marked as imported.'=>'Этот обзор заполняется сам по мере записи визитов; первые появятся в течение минуты. Если в этом году считал другой инструмент аналитики, его историю можно импортировать, и она появится здесь с пометкой «импортировано».','Import history'=>'Импортировать историю','Part of one year was imported from another tool, which counts in its own way, so read the change as a rough guide.'=>'Часть одного года импортирована из другого инструмента, который считает по-своему, поэтому воспринимайте изменение как приблизительный ориентир.','Daily visitors added up. Someone who came on three different days counts three times, because Vireo can\'t recognise anyone from one day to the next.'=>'Сумма ежедневных посетителей. Тот, кто заходил в три разных дня, учитывается трижды, потому что Vireo не может узнать посетителя от одного дня к другому.','Busiest month'=>'Самый активный месяц','Busiest day: %1$s, with %2$s pageview.'=>'Самый активный день: %1$s, %2$s просмотр.' . "\0" . 'Самый активный день: %1$s, %2$s просмотра.' . "\0" . 'Самый активный день: %1$s, %2$s просмотров.','Pageviews by month'=>'Просмотры по месяцам','still to come'=>'ещё впереди','%s pageviews so far this month'=>'%s просмотров с начала месяца','%s pageviews, imported'=>'%s просмотров, импортировано','%1$s pageviews, %2$s of them imported'=>'%1$s просмотров, из них импортировано: %2$s','%s pageviews'=>'%s просмотров','so far'=>'пока','Counted by Vireo Analytics'=>'Учтено Vireo Analytics','Imported'=>'Импортировано','Where these numbers come from'=>'Откуда берутся эти данные','%1$s pageviews this year came from imports and %2$s were counted by Vireo. Imported months are as the other tool counted them, which rarely matches Vireo exactly: tools filter bots and count visitors differently.'=>'За этот год %1$s просмотров получено из импорта, а %2$s учтено Vireo. Импортированные месяцы приведены так, как их посчитал другой инструмент, и это редко точно совпадает с Vireo: инструменты по-разному фильтруют ботов и считают посетителей.','No page-level data for this year.'=>'Нет данных по страницам за этот год.','Published in %d'=>'Опубликовано в %d','Nothing published this year has been viewed yet.'=>'Материалы, опубликованные в этом году, пока никто не просматривал.','Countries from %s onward. Earlier history has no country data.'=>'Страны с %s. За более ранний период данных о странах нет.','Visitors, added up day by day.'=>'Посетители, суммарно по дням.','No country data for this year.'=>'Нет данных по странам за этот год.','How people arrived, in pageviews'=>'Откуда пришли, в просмотрах','mostly %1$s (%2$s)'=>'в основном %1$s (%2$s)','No referrer data for this year.'=>'Нет данных по источникам переходов за этот год.','Top Google searches'=>'Топ поисковых запросов Google','%1$s clicks from %2$s appearances in Google results.'=>'%1$s кликов при %2$s показах в результатах Google.','requests from AI crawlers'=>'запросов ИИ-краулеров','readers sent back'=>'читателей возвращено','Since %s, when Vireo started counting. Imported history doesn\'t record crawlers, so earlier months are left out of both numbers.'=>'С %s, когда Vireo начал подсчёт. Импортированная история не фиксирует краулеров, поэтому более ранние месяцы не учитываются ни в одном из двух показателей.','%s crawler requests for every reader sent.'=>'%s запросов краулеров на каждого приведённого читателя.','Your day on %s'=>'Ваш день на %s','Your daily snapshot · %s'=>'Ваша ежедневная сводка · %s','change against the previous dayDoD'=>'к вчера','Your month on %s'=>'Ваш месяц на %s','Your monthly snapshot · %s'=>'Ваша ежемесячная сводка · %s','change against the previous monthMoM'=>'к прошлому месяцу','Your week on %s'=>'Ваша неделя на %s','Your weekly snapshot · %s'=>'Ваша еженедельная сводка · %s','change against the previous weekWoW'=>'к прошлой неделе','Every minute (Vireo Analytics)'=>'Каждую минуту (Vireo Analytics)','%s event'=>'%s событие' . "\0" . '%s события' . "\0" . '%s событий','Daily traffic chart, no data.'=>'График ежедневного трафика, нет данных.','Daily traffic, %1$s to %2$s. %3$s, %4$s. Use arrow keys to step through each day.'=>'Ежедневный трафик, с %1$s по %2$s. %3$s, %4$s. Используйте клавиши со стрелками, чтобы переходить по дням.','%1$s: %2$s, %3$s'=>'%1$s: %2$s, %3$s',', %s pageview in the prior period'=>', %s просмотр в предыдущем периоде' . "\0" . ', %s просмотра в предыдущем периоде' . "\0" . ', %s просмотров в предыдущем периоде','Note: %s'=>'Заметка: %s','Note on %1$s: %2$s'=>'Заметка к %1$s: %2$s','%1$s: %2$s'=>'%1$s: %2$s','Show fewer'=>'Свернуть','Saving…'=>'Сохранение…','View saved.'=>'Вид сохранён.','The view could not be saved.'=>'Не удалось сохранить вид.','Forgetting…'=>'Забываем…','View forgott